INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('long-term-effects-of-labor-shortage-on-restaurants', 'Long-Term Effects of Labor Shortage on Restaurants', 'The hospitality industry is having trouble finding workers to come back, but that doesn’t mean they’re gone forever. Right now, the industry is experiencing a labor shortage caused by poor wages and treatment, safety...', '[{"type":"p","text":"The hospitality industry is having trouble finding workers to come back, but that doesn’t mean they’re gone forever. Right now, the industry is experiencing a labor shortage caused by poor wages and treatment, safety concerns over COVID-19 and so much more. However once the shortage inevitably ends, the industry will have already changed to account for the lack of workers. The restaurant industry can expect long-lasting effects caused by these months of struggling to hire servers."},{"type":"h2","text":"Better Wages Solve the Labor Shortage"},{"type":"p","text":"The number one reason that workers aren’t flocking back to open restaurants? Insufficient wages. The tipped minimum wage is $2.13/hr federally. Often, people can make more on unemployment benefits than serving full-time and risking exposure to COVID-19. Additionally, more and more restaurants have realized that the solution to their problem is to offer better pay. Workers will flock there if you’re not offering competitive benefits, too."},{"type":"p","text":"In reality, people want to go back to work. Even if they do get paid fairly though, many restaurant workers report unfair treatment in general. As restaurants right these wrongs in an attempt to entice back workers fired or furloughed during the pandemic, offering livable wages and safe environments will become a non-negotiable perk for many potential hires."},{"type":"p","text":"Photo by Konstantin Evdokimov on Unsplash"},{"type":"h2","text":"Menu Prices Rise"},{"type":"p","text":"As wages rise over time, people have more disposable income. Often, menu prices go up to accommodate both increased demand and higher wages, although upper management could also take pay cuts to supplement a livable income for lower-rung workers."},{"type":"p","text":"If you choose to raise your menu prices, do so gradually rather than hiking up the cost of everything all at once. That will be off-putting to customers and even loyal patrons may choose to dine elsewhere. It can also help to explain to guests why prices are going up, even just adding a small note at the bottom of the menu. Mostly, people want to help out their community members. They’ll be happy to forgo tipping and pay a little more per meal to get their servers a fair wage."},{"type":"h2","text":"Technology Meets the Labor Shortage"},{"type":"p","text":"Where there’s demand and no labor to meet it, innovative tech solutions crop up instead. Technology makes it easier for restaurant management to address disruptions in the flow of operations. Whether it’s reducing prep time, streamlining communication between the front and back of house, or automating the arduous accounting process, smart Point of Sale systems meet the changing needs of the industry wherever labor falls flat."},{"type":"p","text":"In the meantime, deal with rampant turnover by relying on intuitive POS devices like the ones powered by eatOS. It’s easy to use and train new workers on the system. Flexible service providers help restaurants through the unpredictable recovery period, through the labor shortage and whatever comes next."},{"type":"h2","text":"What Workers Want"},{"type":"p","text":"Even if you offer competitive benefits at your restaurant, plenty of industry workers will still go where they’re treated well and can make a long-term career. People don’t just need a living wage: They also seek fair treatment, just as much if not more."},{"type":"p","text":"1. Consistent scheduling can provide stability and a work-life balance that makes all the difference."},{"type":"p","text":"2. Give workers control over their shifts. A little more responsibility tends to pay off. For example, eatOS is partnered with 7Shifts, a smart scheduling software that makes it easy to swap with coworkers digitally without manager permission."},{"type":"p","text":"3. Flexible scheduling is a must, particularly when it comes to time off. Employees want PTO, sick days and to be met with understanding when personal emergencies happen."},{"type":"p","text":"4. Promote from within to show workers they can rise through the ranks and really develop professionally at this establishment."},{"type":"p","text":"Ultimately, service workers just want to be treated like human beings. Respect and proper treatment go a long way toward retention. Even once you eventually hire back a full staff and reach pre-pandemic levels of business, these expectations are taking hold of the industry. Like higher menu prices, workers demanding better pay and treatment will remain even once the labor shortage passes."},{"type":"p","text":"Photo by Fabrizio Magoni on Unsplash"},{"type":"p","text":"Is your restaurant ready to get back to work? Hire, retain and manage workers better with a smart Point of Sale system."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurant #LaborShortage"}]', 'https://static.wixstatic.com/media/a77ed6_7312dca5235d4adc957fed0bb7dfbac1~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-05-25', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('loyalty-programs-the-future-of-takeout', 'Loyalty Programs: The Future of Takeout?', 'Photo by Blake Wisz on Unsplash', '[{"type":"p","text":"Photo by Blake Wisz on Unsplash"},{"type":"p","text":"COVID-19 permanently changed the face of dine-in seating. Over the past year, customers have had to rely more on online ordering solutions when lockdown orders make sit-down service impossible. If you’re a restaurant owner, you need to find a way to increase takeout customers now that off-premise ordering is a primary source of revenue. Loyalty programs are the fix you need."},{"type":"p","text":"Customers who join a rewards program spend twice as much on average as non-members. The National Restaurant Association reports that one-third of consumers said they were more likely to choose one restaurant over another if they had a loyalty program, further cementing their importance in the eyes of both industry professionals and their patrons."},{"type":"p","text":"Now that customers rely on takeaway service, restaurants need to focus more on optimizing these programs for their online ordering channels."},{"type":"h2","text":"Why Do Loyalty Programs Matter?"},{"type":"p","text":"Rewards incentivize guests to return again and again. A good loyalty program…."},{"type":"p","text":"1. encourages more frequent spending."},{"type":"p","text":"2. increases the average ticket size of each order."},{"type":"p","text":"3. is online so customers don’t have to deal with lost or damaged punch cards, a massive problem before digitization."},{"type":"p","text":"4. builds customer profiles that you need to make smarter business decisions and marketing campaigns."},{"type":"p","text":"Online ordering platforms are the perfect place to integrate points. By simply requiring guests to sign in before placing an order, you’ll get sales trends and data for your best customers over long periods of time. With an app and website, it’s a quick process for customers to sign up and start collecting points."},{"type":"p","text":"Smart Point of Sale systems aggregate all those online channels and generate automatic reports for your analysis. See when your best customers come in and what they order when they do; this lets you build targeted campaigns designed to give your loyal customers what they want. Sales analysis also reduces over- or understaffing; when you see how busy you were over a major holiday last year or on a certain night of the week, you’ll schedule smarter and reduce labor expenses."},{"type":"h2","text":"Phasing Back Into Dine-In Seating"},{"type":"p","text":"The limitations on dine-in services makes it necessary to focus on off-premise orders and grow that customer base. Even as contact-free ordering becomes increasingly relevant, keep in mind that your customers won’t have to stay at home forever."},{"type":"p","text":"Although your loyalty program should lean on online ordering, dine-in seating will eventually phase back in. When you focus so heavily on optimizing rewards with takeout orders, and incentivizing guests to buy from you that way, you run the risk of making them entirely reliant on your delivery channels. Dine-in services pull more profit on average than takeaway does. Build adaptability into your marketing strategy so you can get the most out of your takeout and delivery now, and still be flexible enough to seamlessly expand it to include dine-in services when you pivot back to normal."},{"type":"p","text":"COVID-19 has made online ordering extremely important to customers, so build a loyalty program that caters to their need for fast and contact-free service while also providing incentives to come to your restaurant in-person soon. Especially considering the popularity of third party apps, restaurants have a lot of competition in the online sphere and need a hook to stand out."},{"type":"p","text":"For example, QR codes that lead to a digital menu can be placed in the restaurant for customers to use. Self-ordering through a mobile device increases order accuracy and promotes continued contact-free service, while still relying on customer profiles. Sit-down guests who are part of a loyalty program spend an average of over 92% more than non-members do."},{"type":"p","text":"Photo courtesy of eatOS."},{"type":"h2","text":"The Future of Food Service"},{"type":"p","text":"Get the most out of your rewards program and online ordering platforms when you make them work together. With a superior Point of Sale system, your restaurant will be equipped to handle the COVID-19 situation as it evolves."},{"type":"p","text":"#eatOS #LoyaltyProgram"}]', 'https://static.wixstatic.com/media/a77ed6_b17eee13084741d3bd816e9c963b44a1~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2021-05-20', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('maintaining-a-healthy-staff', 'Maintaining a Healthy Staff', 'Now more than ever, owners of essential businesses worry about the health and safety of their employees. Many seek proper measures that ensure sick workers stay home to prevent the spread of COVID-19 and other diseases.', '[{"type":"p","text":"Now more than ever, owners of essential businesses worry about the health and safety of their employees. Many seek proper measures that ensure sick workers stay home to prevent the spread of COVID-19 and other diseases."},{"type":"p","text":"Your business can’t run well without staff. Staff can’t work their best if they’re sick. To ensure a safe and healthy work environment for you, your employees, and all the customers who use your essential services, protect your staff through this pandemic and beyond."},{"type":"h2","text":"provide paid sick and family leave"},{"type":"p","text":"The majority of employees who come to work sick simply have no other option. Foodservice industry workers already contend with some of the lowest wages and poorest working conditions; they can’t afford to take a day off if they worry about making rent even on a good month. Giving them a secure safety net lets them isolate themselves when they’re sick without the fear of losing their job, income, and housing. Workers don’t want to spread the disease to others; mostly, they just don’t have any other choice."},{"type":"p","text":"Similarly, ease some other restrictions around staying homesick. Some employees need a doctor’s note to get time off. However, many low-wage workers can’t afford a doctor’s visit; price aside, going for a check-up means taking time off work which again, many people can’t afford. This struggle only intensifies for workplaces that don’t offer any health benefits. The doctor’s office is costly, and without insurance, many workers can’t afford to go even if they had the time. If you’re not prepared to offer them benefits, at least remove the obstacles around staying home and getting rest and care."},{"type":"p","text":"Also, consider offering paid family leave. With many diseases, but COVID-19 especially, older generations and immunocompromised people are the most at-risk. Children, the elderly, and people who have other health concerns on top of their illness might need someone to help look after them. Giving your employees paid time off to take care of family will help protect those most vulnerable in our society."},{"type":"p","text":"If an employee doesn’t qualify for paid time off under the Family and Medical Leave Act (FMLA) then you can work something out with them so they can still care for themselves and their family without risking unemployment, for example, a more flexible schedule or reduced hours. Check here to view FMLA requirements."},{"type":"h2","text":"support mental health"},{"type":"p","text":"Mental health is just as important as physical health. Everyone understandably feels a tremendous amount of fear, concern, and confusion during this time; helping your staff grow more comfortable and at ease will foster a happier, healthier working environment."},{"type":"p","text":"Promote de-stressing techniques to alleviate anxieties. This can involve meditation and mindfulness apps, reminding staff that there’s no shame in therapy and certified coaches, and providing other digital resources that they can access over the phone, online, or via video call. Considering your staff’s mental health lets them know that you care about them and want to support them through this."},{"type":"h2","text":"policy of honesty"},{"type":"p","text":"New guidelines, restrictions, and regulations about this pandemic come out weekly; the predictions of when this will be over changes just as often. Instead of sugarcoating the situation, which your employees will see through, establish a policy of openness and honesty with them especially regarding the procedures you set in place to defend against this virus. Not only will this cultivate trust and ease some of their concerns about what will happen to the business, but it indicates that you’ll take the necessary steps to keep everyone safe."},{"type":"p","text":"Let your employees know what you’re doing to follow the guidelines set by the CDC and state health organizations, why you’re setting certain rules in place, and what you’re doing to promote general health and wellbeing in the community. Even if you only delegate a couple of minutes in a team meeting to do so/, transparency will go a long way into helping your employees comply with legal regulations and encouraging mental and physical health."},{"type":"h2","text":"prioritize cleanliness"},{"type":"p","text":"Of course, keeping a clean restaurant should always be a top priority. Complying with federal health regulations ensures you can stay open. However as we strive to contain the spread of COVID-19, everyone needs to work harder than usual to prevent the spread of germs in your workplace. Use these basic hygiene tips through COVID-19 and beyond:"},{"type":"p","text":"1. Use proper handwashing techniques. Everyone needs to wash after they use the bathroom when they begin preparing new food and after touching communal surfaces. Remember to spend twenty seconds washing with soap under hot water."},{"type":"p","text":"2. Cover sneezes and coughs. Even if you’re not sick, always cover a cough or sneeze with a tissue or your elbow, never into your hand."},{"type":"p","text":"3. Use hand sanitizer. You can put out containers for the front and back of the house so that it’s accessible to your staff as well as any delivery drivers or customers who come in to pick up an order."},{"type":"p","text":"4. Clean more often than usual. Though you likely have cleanup procedures in place already, you should increase how often you clean during the day. Sanitize equipment and surfaces regularly throughout the day to prevent germs from spreading between kitchen staff, delivery workers, and customers. Especially make sure to frequently sanitize communal objects that get touched by a lot of people, such as door handles, pots and pans, and other equipment."},{"type":"p","text":"5. Ensure everyone follows the six-foot rule. If possible, reduce the number of staff on shift to only those you need to successfully operate. If you aren’t busy, send some workers home so the necessary staff can more easily avoid getting too close to one another."},{"type":"p","text":"While health and cleanliness always matter, maintaining a sanitized work environment is especially important during a crisis like this one. Taking these easy steps helps you, your workers, and all of your customers avoid infection."},{"type":"h2","text":"let technology fill in the gaps"},{"type":"p","text":"While you contend with a smaller staff, slower shifts, and a brand new focus on delivery-only service, let technology smooth the way into this new normal. Most if not all restaurants have implemented measures like online ordering and contactless delivery to prevent too much face-to-face contact, which would violate the six-foot guideline for social distancing."},{"type":"p","text":"However, even after the imminent threat of COVID-19 fades, our collective fear of spreading disease and getting too close will likely remain in the public consciousness for a long time. Many POS vendors offer services that cut down on face-to-face time between workers and customers, and make self-service and contactless service easier. Self-service kiosks, contactless payment methods, handheld POS devices and other high technology are all becoming more popular as restaurants strive for ease, innovation, and now toward better health as well. As we move into a post-COVID-19 world, we can expect a certain amount of social distancing to remain the norm."},{"type":"p","text":"Contact eatOS today to learn about how which products can help you promote quick, quality servicefrom an appropriately safe distance. Click here for how to do it."}]', 'https://static.wixstatic.com/media/a77ed6_c95f550501f64fd799374186116bef42~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-05-18', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-a-consultant-can-help-your-restaurant', 'How a Consultant Can Help Your Restaurant', 'Managing a restaurant is no easy task. When you run up against roadblocks and don’t know what to do, then hiring a consultant might be the answer. They can help with all manner of tasks throughout the restaurant, as...', '[{"type":"p","text":"Managing a restaurant is no easy task. When you run up against roadblocks and don’t know what to do, then hiring a consultant might be the answer. They can help with all manner of tasks throughout the restaurant, as well as shed light on issues that you don’t otherwise know how to solve."},{"type":"h2","text":"What Does a Restaurant Consultant Do?"},{"type":"p","text":"They can play many different roles in your organization depending on your weak spots and what you’d like to improve. It helps to have a purpose in mind when you hire a consultant. For example, consultants can educate your staff on various processes or provide resources for more information. If you need to make adjustments to the flow of operations, they’ll help guide your organization onto a more profitable track too."},{"type":"p","text":"Photo by John Schnobrich on Unsplash"},{"type":"p","text":"In general, a consultant shows you how best to succeed in the current market. Because they check in regularly, they bring news of trends seen throughout the industry as well as their own network. Thus, your restaurant stays up to date with the latest tips and tricks for growth. The business will also…"},{"type":"p","text":"1. learn the best suppliers based on efficiency, whose operations are eco-friendly or any other metric you value."},{"type":"p","text":"2. get tips for successfully launching your business or appealing to your target audience, whomever they might be."},{"type":"p","text":"3. try recommendations for vendors, maintenance teams, support staff and more."},{"type":"p","text":"Consultants are meant to help the restaurant out of any tough situation that it might face. All businesses could benefit from an objective, third party analysis of how they run, so clear eyes combined with outsider industry knowledge give an unbiased outlook on your likeliest factors for success."},{"type":"h2","text":"Set Specific Goals to Get Insight For"},{"type":"p","text":"Different consultants offer solutions to any problem you may have. Do you need help hiring and training new employees? Creating new business strategies and management systems? Maybe accounting is difficult and arduous, and could benefit from streamlining. There’s consultants for that, too."},{"type":"p","text":"Whatever your weak points, find them and hire someone whose job it is to make it all easier to handle. Together, you can develop new protocols and restaurant systems that work for your individual business. Together, you can build a smarter and more capable restaurant."},{"type":"p","text":"the best way to streamline operations and handle more satisfied customers is to invest in the latest Point of Sale technology. From building guest profiles to analyzing the most profitable trends and deals on the menu, advanced POS devices will bring your restaurant to the next level."},{"type":"p","text":"#eatOS #Restaurant #RestaurantBusiness #RestaurantManagement"}]', 'https://static.wixstatic.com/media/a77ed6_d69487c7583f43d5bf664e5f82e2128e~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-05-13', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-can-restaurants-support-pride-month', 'How can restaurants support pride month?', '1. Make your business an affirming place for LGBTQ+ customers at any time, not just during Pride Month. That could mean posting a sign in your window that expresses inclusivity or a Pride flag to let LGBTQ+ people and...', '[{"type":"p","text":"1. Make your business an affirming place for LGBTQ+ customers at any time, not just during Pride Month. That could mean posting a sign in your window that expresses inclusivity or a Pride flag to let LGBTQ+ people and allies know that they’re safe and welcome inside your doors."},{"type":"p","text":"2. Educate yourself and your staff on LGBTQ+ issues and history. This can help create a more inclusive environment for all of your customers, not just those who identify as LGBTQ+."},{"type":"p","text":"3. Sponsor or participate in local Pride events. This is a great way to show your support for the LGBTQ+ community while also promoting your business."},{"type":"p","text":"4. Donate to LGBTQ+-friendly organizations or causes. This is a great way to give back and show your support for the community."},{"type":"p","text":"By taking these steps, you can show your customers that you’re an inclusive business that supports the LGBTQ+ community. This, in turn, can help you attract new customers and build loyalty among your existing customer base."}]', 'https://static.wixstatic.com/media/35ab20_ca960b5e9a53459ca98ccd58cdbe96f3~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-05-11', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-can-we-revitalize-restaurants-during-and-after-the-pandemic', 'How Can We Revitalize Restaurants During and After the Pandemic?', 'Photo by Pablo Merchán Montes on Unsplash', '[{"type":"p","text":"Photo by Pablo Merchán Montes on Unsplash"},{"type":"p","text":"Restaurants around the world are in real trouble. The COVID-19 pandemic has either significantly cut revenue or completely shut down most restaurants."},{"type":"p","text":"There has been a huge community movement to try and save restaurants and workers through grants and fundraising campaigns like the Restaurant Employee Relief Fund, Another Round Another Rally, and as well as hundreds of local community grants."},{"type":"p","text":"The government has also attempted to help restaurants with a loan forgiveness program. When restaurants follow specific rules, these government loans are forgivable so restaurants won’t have to pay them back. Even if restaurants do have to eventually pay back the loan, like most government loans the interest will be relatively low."},{"type":"p","text":"But there is a question of how can we let restaurants save themselves?"},{"type":"p","text":"In the long run, loans and grants will not save the restaurant industry. The only way to create meaningful sustainability is through programs that pave the way through the pandemic and even recovery after."},{"type":"h2","text":"Customer Confidence"},{"type":"p","text":"The first and most enduring issue restaurants must tackle is customer confidence. Even if a vaccine for COVID-19 were to be discovered tomorrow surveys have shown that most consumers are still wary of being vulnerable in public spaces."},{"type":"p","text":"There are multiple reports where restaurants are vectors of the virus and have caused super spreader events that may have contributed to the massive surge in new COVID-19 cases across the US. The CDC has also classified indoor dining at restaurants as one of the highest risk activities consumers can do during a pandemic."},{"type":"p","text":"Multiple surveys from OpenTable and Eater indicate that over 70% of diners are not ready to eat out even if the lockdown ends. Roughly 30% of people surveyed will not eat out until the pandemic is over and a small portion of people, roughly 8%-12% depending on the survey, will wait long after the pandemic ends to eat out again out of precaution."},{"type":"p","text":"The only way to inspire confidence in the public is by making restaurants as safe as possible through enforcing strict health and safety guidelines preventing restaurant-related outbreaks. That may mean restaurants have to do their own research to find out what is the best practice for their own establishment and not rely too much on overly generalized guidelines from the local and federal government."},{"type":"p","text":"Restaurants will have to go above and beyond the minimum recommended guidelines to make customers feel safe and confident enough to go back to dine-in. But just as important, customers must see you make the effort and have safety measures clearly communicated."},{"type":"p","text":"_PHOTO: OpenTable_"},{"type":"h2","text":"Government Initiatives"},{"type":"p","text":"As important as it is that restaurants be proactive about the health and safety of diners there is only so much they can do without government help."},{"type":"p","text":"One way governments can help is by subsidizing meals. The UK Chancellor Rishi Sunak announced that diners will receive a 50% discount off their restaurant bill during August as a way to get customers back into restaurants, cafes and pubs and protecting the 1.8 million people who work in them."},{"type":"p","text":"His announcement was highlighted by the fact that the UK was facing a unique moment because of Covid-19, adding: We need to be creative."},{"type":"p","text":"The discount will not apply to alcohol but may be used unlimited times on food and drink for participating restaurants, cafés, and pubs across the UK."},{"type":"p","text":"To clarify how restaurants will recoup the discount, Chancellor Sunak said, Each week in August, businesses can then claim the money back, with the funds in their bank account within five working days."},{"type":"p","text":"New cases of COVID-19 have been on the decline for the last two months in the UK, a stark contrast to the US which is at an all-time high for new COVID-19 cases. The US will likely not be able to implement such an idea until the new cases are under control but the government can certainly come up with new initiatives to reinvigorate the restaurant industry."},{"type":"h2","text":"Private Companies; Delivery Apps"},{"type":"p","text":"As new cases rise, states are reversing re-opening the economy restaurants are forced to turn to third-party delivery platforms like Uber Eats, Grubhub, Postmates, and DoorDash to keep their businesses afloat through delivery. On the surface, it appears these companies are providing a necessary service, letting restaurants use their enormous platforms to reach hungry diners stuck at home. But theyve has a history of anti-consumer and anti-restaurant policies."},{"type":"p","text":"Not only do third-party delivery platforms often have hidden fees for hungry diners but they also charge ridiculously high commission fees for restaurants. Most commissions average around 20%-30% per order but can go as high as 40% per order."},{"type":"p","text":"Restaurants usually have about 90% of their costs as fixed costs tied to rent, labor, and food. The current commission fees are essentially a death sentence for many smaller community restaurants."},{"type":"p","text":"Private companies that rely on restaurants must take measures to protect their livelihood which in turn fosters goodwill and a shared cooperative future."},{"type":"p","text":"Due to backlash, companies have announced they would take steps to work with restaurants and reduce fees and commissions. So far, mostly large chain restaurants have negotiated/received lower commissions due to the volume of orders they can bring in."},{"type":"p","text":"Grubhub announced in March that they would suspend collecting commissions from independent restaurants up to $100 million. Multiple independent restaurants have confirmed that the suspension of commission fees is simply deferred to a later date. Restaurants will have to pay back the deferred fees."},{"type":"p","text":"The situation has become so grim local governments were forced to step in. Cities like Los Angeles, New York City, Chicago, and others passed legislation that caps how much third-party delivery apps can collect in commissions from restaurants. In most cases, the cap has been lowered to a manageable 10% in commission. But local restaurants in areas with capped commissions report that delivery companies are giving them the runaround. Despite legislation passed weeks or even months ago, companies like Grubhub and Postmates still havent complied."},{"type":"p","text":"When asked why they havent complied, delivery platforms have feigned ignorance or blamed legal holdups."},{"type":"p","text":"A restaurant owner in Los Angeles received this message from Grubhub, We are waiting to hear back from our legal team on how we will proceed. Once the fee cap is applied you will receive a refund for the commission difference."},{"type":"p","text":"Some restaurants were able to receive the correct commission percentage after extensive communication, but many restaurants are still stuck with the high commission."},{"type":"p","text":"Uber Eats combats the lower commission cap by charging an extra $3 fee to the customer and reducing the delivery distance to restaurants."},{"type":"p","text":"It is imperative to let restaurants keep as much of their diminishing revenue as possible to survive. Private companies that depend on the vibrant community-oriented restaurant industry need to cooperate for the future."},{"type":"p","text":"#Covid19Pandemic #RestaurantTechnologyandCOVID19 #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_d4469f2cb3054fc1958454a10b64155d~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-05-06', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-gen-z-is-changing-the-restaurant-industry', 'How Gen Z Is Changing The Restaurant Industry', 'A lot of markets are beginning to take Gen Z seriously as consumers. As they age out of their youth with no disposable income and become young adults with their own spending habits and consumer preferences like every...', '[{"type":"p","text":"A lot of markets are beginning to take Gen Z seriously as consumers. As they age out of their youth with no disposable income and become young adults with their own spending habits and consumer preferences like every generation before them, industries are starting to take them more seriously and understand their importance. As Zoomers expectations toward dining out change, restaurants have to adapt in ways they never have before in order to continually attract this generation as repeat customers."},{"type":"p","text":"It can be hard to grasp the needs of a new target audience. eatOS wants to provide a closer look at some of Gen Z’s consumer beliefs and values so that restaurateurs can get a handle on themand start marketing successfully."},{"type":"h2","text":"Speed & Convenience"},{"type":"p","text":"Gen Z grew up with modern technology and an on-the-go mindset. They like instant gratification, and that naturally extends to their expectations for food service: Fast, convenient and customizable dining that brings them exactly what they’re craving and to their exact specifications."},{"type":"p","text":"This is one driver for restaurants’ increasing automation and reliance on technology. Devices like Self-Service Kiosks ensure that customers can get exactly what they want with much shorter wait times; modern restaurant technology increases table turn times and order accuracy while simultaneously bolstering average check size and customer satisfaction."},{"type":"p","text":"Gen Z is just as reliant on technology as one would expect. They enjoy the convenience of third party delivery, which is why it’s so important for restaurants to develop online ordering streams. Smartphones increased capabilities means that many Zoomers order on the go or want to pay with touch-free transaction systems, even when they dine in. It’s important that restaurants can meet these expectations. However businesses should focus on social media just as much as the functional aspect of their online presence: Strong engagement translates to better in-person loyalty, and many Zoomers will skip out on trying a new restaurant if their social media is sparse and uncompelling. Never underestimate the power of a clean Instagram page."},{"type":"h2","text":"Affordable Togetherness"},{"type":"p","text":"Gen Z is bringing back the family dinner in a new way by sharing meals with their chosen family instead. This is tied into their preference for fast-casual dining; they want to be able to hang out and enjoy a relaxed meal with friends, so restaurants need to cater to the atmosphere _they_ want rather than Gen Z going into full -service restaurants and adapting to the ambience that the restaurant sets. The tables have turned. Gen Z is setting the trends and brands are expected to align, not the other way around."},{"type":"p","text":"As a result, Gen Z has a tendency to adapt brands into part of their image; brands are a lifestyle choice, not just a financial decision anymore. Because their purchases are increasingly part of their “personal brand,” Gen Z is willing to pay a bit more for healthier dining options, but overall they like their meals cheap. Affordability is big with this generation, because they grew up in a post-recession America that never really got its “thriving” economy back. They’re habitually more careful with money, so menu options need to be cheap to attract Zoomers to you over your competitors."},{"type":"p","text":"Despite this, or because of it, their standards are higher than ever. If they’re going to spend money on you then quality had better live up to expectations. Simultaneously, Gen Z is more likely to “graze” than sit down for a full meal, which ultimately balances out: They would rather buy lots of sides and reduced portions so the whole table can share everything with each other, so businesses can lower the prices of each individual item since they’re serving smaller-sized dishes. Everybody wins."},{"type":"h2","text":"Intrigue"},{"type":"p","text":"Restaurants are rising to the challenge of new, experiential customer service designs because as long as theyre meeting Gen Z’s core values, there’s room for owners to get a little creative. Moreover, it’s smart to try out new restaurant concepts now and then: Gen Z grew up on instability. With a recession, a deepening political divide and the past two decades of rapidly-changing tech, this generation is used to new inventions every other day. Theyre used to constant newness, so restaurants need to win their attention again and again and again."},{"type":"p","text":"Gen Z isnt as loyal as past generationsthough that in part can be attributed to their relative youth, how they’re still discovering what they like, and settling into adult routines and preferences. Gen Z likes to be first on new trends and discover the next cool idea. They’ve also grown up in a period of increased globalization so trying new foods is high on their list of experimental ideas. More than other generations, they’re willing to try cuisines they’ve never had before. Interesting flavors are just as important as organic ingredients and healthy living; in fact, authenticity and realness can be more important than other considerations sometimes. They prefer that businesses are transparent; food quality needs to match up with the hype, and Gen Z likes authentic experiences especially when they’re trying something new."},{"type":"h2","text":"Social Consciousness"},{"type":"p","text":"Just because they believe in convenience and cheap menu options doesn’t make this generation selfish. In fact, they place just as much emphasis on respectable business practices as they do on self-gratification. As much as they enjoy experimenting with new dishes they’ve never tried before, having organic and ethically-sourced ingredients matters just as much to them."},{"type":"p","text":"Overall, though, environmentalism was Millennials’ social cause. Increasingly, Gen Z champions better working conditions and business practices in general. In part because they also work service industry jobs, Zoomers care that their money goes someplace that pays fair wages, hires inclusively and diversely, and respects their employees. Gen Z cares about dining together because of an increased focus on community amongst themselves; it makes sense they want to see their businesses extend the same care to the community at large."},{"type":"p","text":"Gen Z is grown up and bursting into the marketplace with a bang. With their increased devotion to the global community, technology, affordability, convenience and social responsibility, restaurateurs have their work cut out for them finding marketing techniques that will be uniquely appealing to this new generation of consumers. One thing is for sure, Generation Z is permanently changing the restaurant industrythe only real question remaining is what trend they’ll invent next."},{"type":"p","text":"Stay on top of industry news and maximize the success of your restaurant when you sign up with eatOS. Schedule a demo today and let us show you how we’ll improve your staff management, customer relationships and more. The future of food service is now."},{"type":"p","text":"#eatOS #FoodService #RestaurantBusiness #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_89410d140a1f48129c3fac0cfe27620f~mv2.jpeg', 'Online Ordering', 'eatOS Staff', '2021-05-04', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-much-does-a-bar-cost-to-open', 'How Much Does a Bar Cost to Open?', 'So the COVID-19 pandemic is finally waning, and you’re ready to open up the bar you’ve been dreaming about. The expenses associated with running a business vary depending on several factors, and you should be aware of...', '[{"type":"p","text":"So the COVID-19 pandemic is finally waning, and you’re ready to open up the bar you’ve been dreaming about. The expenses associated with running a business vary depending on several factors, and you should be aware of them before taking on a new venture."},{"type":"p","text":"As you get ready to open up a bar, consider these 3 big influencers of your budget."},{"type":"p","text":"Photo by Helena Lopes on Unsplash"},{"type":"h2","text":"The Cost of Starting a Bar"},{"type":"h2","text":"1\\. Location"},{"type":"p","text":"Where do you plan to start this new venture? Not just the state, but the local jurisdiction matters too. City business taxes, for example, usually hover between 5 to 10K. Meanwhile, whether you plan to rebuild an existing space or from the ground up matters. Taking over where similar businesses used to operate will likely mean that you don’t have to invest in a lot of the core requirements that health inspectors have for the floor plan, like ventilators and certain-size doorways."},{"type":"p","text":"Building from scratch can cost more than 100K; if you rent, you’ll pay less before opening but it will also vary wildly depending on how well-trafficked the area is. Rent is high in big cities where people flock; but the costs may be worth it if there’s not a lot of competition nearby, and the customers will definitely come to you. Take all of this into account as you consider where to open your bar."},{"type":"h2","text":"2\\. Bar Licensing"},{"type":"p","text":"You’ll definitely need liquor licenses, but did you know that you may need separate ones for beer, wine and liquor? Fees differ between cities and states too. Getting your bar licenses all up to date can cost anywhere from hundreds to thousands of dollars. You may want to start saving early or adjust your budget depending on the associated fees of starting a new business."},{"type":"p","text":"The type of bar you run matters since you need different kinds of alcohol licenses anyway. You could open a wine bar, brewery or the hottest social hangout. Each different choice affects what you’ll need to run legally. And even then, liquor sales aren’t the only thing to fill out an application for. Check out ten hospitality licenses you’ll need before opening."},{"type":"h2","text":"3\\. Size"},{"type":"p","text":"Where you open and what kind of bar you want to run both influence the ideal size of your business. Do you want multiple venues? Maybe you plan to start in a big city, meaning you’ll probably have less floor space to work with. However, physical size isn’t the only kind to consider."},{"type":"p","text":"It also refers to your staff. Ideally, have at least six months’ payroll ready before opening, so there’s time to become solvent. This could equal anywhere between 50 to 100K depending on how many employees you hire, and whether you plan to offer competitive wages too. Your staff also plays a role in the cost of insurance, so take all of this into account when planning your new business."},{"type":"p","text":"Photo by K elly Sikkema on Unsplash"},{"type":"h2","text":"How to Open a Bar on a Budget"},{"type":"p","text":"All of these opening considerations can seem daunting, and expensive. Budgeting will help smooth the takeoff."},{"type":"p","text":"Keeping a clean and straightforward budget lets you track the bar’s health over time, and permits a long-term plan for growth. A strong budget streamlines operations down to what you need for success, so you can reduce some of these hefty costs of doing business. Learn better budgeting skills with a smart Point of Sale system that can analyze sales reports to save you both time and money."},{"type":"p","text":"#Bars #eatOS #PointofSaleforRestaurants #RestaurantBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_311606a745194ee080fb8b5056ed012b~mv2.jpg', 'Restaurant Growth', 'eatOS Staff', '2021-04-29', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-much-should-your-restaurant-pay-its-employees', 'How Much Should Your Restaurant Pay Its Employees?', 'Restaurant staff: They’re the face of your business and the reason that operations run so smoothly. They’re the go-between for your restaurant and every customer that comes in, dedicated to providing a superior...', '[{"type":"p","text":"Restaurant staff: They’re the face of your business and the reason that operations run so smoothly. They’re the go-between for your restaurant and every customer that comes in, dedicated to providing a superior experience for them. That’s why it’s so important to attract fantastic employees so you can foster the best customer experience possible."},{"type":"p","text":"Currently, the industry is growing nearly twice as fast as the rate of workers looking to fill necessary roles. Finding your competitive edge will not only entice job seekers to you over your competition but potentially even get people to join the industry for the first time."},{"type":"h2","text":"How to Gain A Competitive Edge"},{"type":"p","text":"Employees are, by and large, mainly motivated by one thing: Compensation. Whether via wages or other perks, workers need incentive to join you over another restaurant with all else being equal. Competitive salaries are a great way to encourage candidates to apply with you."},{"type":"p","text":"Unfortunately, there’s no perfect standard; there’s no single number that we can give about what exact salary to offer new employees. The wages you can afford depend on your profit margin, the laws in your state, your tipping versus gratuities structure, and more."},{"type":"h2","text":"Deciding on Pay"},{"type":"p","text":"Each employee’s pay is typically determined by their role in the business. Are they waitstaff or cooks? Hosts or runners? All of this affects the average compensation for that role and what you’re actually willing to pay. You want to be sure that the responsibility of each role matches their wages."},{"type":"p","text":"You should also consider if you’re going to use a tipping model, gratuity model, or something else. If you plan on subsidizing employees’ wages with tips, then the federal minimum wage is $2.13 as long as they make up the rest in tips every paycheck cycle, and the business gets a tip credit. You also need to consider how to tip out your employees. For example, some restaurants do tip pooling, and others share tips with the back-of-house staff. All of this will affect potential employees’ opinions on working with you. Look into the legal regulations surrounding tips and gratuity laws, its effect on salaries, and how that will change your tax filing and reporting."},{"type":"p","text":"However well you’d _like_ to pay employees still doesn’t mean much unless you can actually afford it. To best determine how much to pay the staff, determine the highest and lowest salary you’re willing to offer each position. You might ask questions like:"},{"type":"p","text":"1. Does this role drive operational growth or streamline efficiency?"},{"type":"p","text":"2. What would similar and nearby food service establishments offer for this same job?"},{"type":"p","text":"3. How much would an experienced candidate expect?"},{"type":"p","text":"4. Can the discrepancy between our highest and lowest paid staff incentivize working harder for the promise of upwards mobility?"},{"type":"p","text":"Oftentimes, workers just want to move up in the world. A competitive salary one step up from what they earned before can be indicative of career growth and thus more enticing than just earning the same exact wages they were at their last job. Though you can circumvent this by hiring fresh faces with little to no experience, you also risk hurting your business with less capable employees as well as more time and money spent on training."},{"type":"p","text":"Keeping all of this in mind along with federal and local labor laws, overtime, and adherence to the Fair Labor Standards Act, you can determine the highest and lowest amount you’d be willing to pay for the role and then begin negotiations with promising candidates from there."},{"type":"h2","text":"Other Benefits and Perks"},{"type":"p","text":"Frankly, nothing beats a living wage. Industry employees talk just like businesses do; word of mouth doesn’t exclusively apply to advertising. You’ll draw in better employees by offering competitive pay and treating them right, because word will get around."},{"type":"p","text":"However, as many restaurants begin to catch on to the power of the paycheck, you might seek out other opportunities to draw candidates to you. Offering perks and benefits will set you apart from the masses. You might consider giving your staff health insurance, paid time off, vacation days and other benefits. Oftentimes people want acknowledgement of their hard work, so it can incentivize productivity to do things like recognizing the employee of the month or buying dinner for particularly outstanding shifts. Perks and benefits can really motivate your team to do their best."},{"type":"h2","text":"Set Employees Up For Success"},{"type":"p","text":"As important as good pay is, don’t underestimate the power of a positive work environment. This fosters better employee-management relationships more than you might think; supportive companies mean a lot to staff members on an individual level. Many employees also find it important to have a friendly relationship with coworkers as well as career opportunities for promotions and professional development."},{"type":"p","text":"It’s beneficial to create a comfortable and positive workplace anyway. More contented employees work harder and don’t have to dig as deep to give that standard service with a smile. Restaurants that get rated as better places to work also tend to have greater customer satisfaction overall. Happy employees make happy guests."},{"type":"p","text":"Employees want to feel good about going into work. You’re in a position to make that happen."},{"type":"h2","text":"Attract and Retain Workers"},{"type":"p","text":"Cultivating a comfortable, supportive work environment is massively useful for drawing in top-notch candidates with impressive resumes. It can be difficult and time-consuming to weed out exceptional candidates all of it begins with the job posting itself. Once you recruit a good core staff, train them well so they don’t have to spend much time learning the ropes and can be well prepared to hit the ground running."},{"type":"p","text":"There’s no one-size-fits-all when it comes to properly compensating your employees. Every worker and restaurant has different expectations when it comes to benefits, perks and pay. Understanding each other’s needs as well as your own, researching local and federal laws, scoping out the competition and calculating what your restaurant can personally afford is a good place to start wage negotiations with each new employee."},{"type":"p","text":"#eatOS #WorkforceManagement"}]', 'https://static.wixstatic.com/media/a77ed6_746b0fb336ee4bcb9454a941298a63cd~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-04-27', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-qr-codes-boost-restaurant-engagement', 'How QR Codes Boost Restaurant Engagement', 'Lately, restaurants have adopted new self-service solutions to guarantee a more streamlined, safe, and accurate customer experience. With social distance, a legitimate concern still appeals directly to your best guests....', '[{"type":"p","text":"Lately, restaurants have adopted new self-service solutions to guarantee a more streamlined, safe, and accurate customer experience. With social distance, a legitimate concern still appeals directly to your best guests. It increases the likelihood that they’ll recommend you to their friends and family when you invest in cutting-edge technology like QR codes which are sweeping the market alongside other contactless digital options."},{"type":"p","text":"Build in coronavirus safety precautions and provide a better customer experience without sacrificing one for the other. As you cultivate the best possible service, you’ll beget happier customers, and that pads your bottom line."},{"type":"h2","text":"The Upsides of QR Codes"},{"type":"p","text":"Advancing technology doesn’t force a compromise between convenience and better service. The inherently compact nature of a QR code that links to digital platforms guarantees that it doesn’t take up too much space, which gives you room to fit more guests in without breaking social distance measures or capacity restrictions."},{"type":"p","text":"Choose the optimal place for a code based on the personal needs of your audience. If they spend a lot of time lingering up front, post a few on the wall in the waiting area, so they don’t sit around deliberating what to eat later. If you get a lot of foot traffic, maybe post up your takeout code in the storefront window."},{"type":"p","text":"A digital menu for browsing takes your customer relationships to the next level. You aren’t limited to showing them what’s good to eat; the beauty of QR codes is that you can generate several different ones. For example, many restaurants are creating virtual online experiences to generate revenue. Link to videos of your chefs walking through fan-favorite recipes step by step for guests to enjoy at home or come up with your own creative ideas that fit your brand."},{"type":"p","text":"With technology, the sky’s the limit. Rewrite the URL, and those changes automatically go into motion; this saves a lot on printing costs and doesn’t hold you back from making small tweaks to your digital menu, like raising the best-seller price a few cents or optimizing items’ positions for more significant sales. Even customize the QR code’s look to better match your brand aesthetic and give customers a kick."},{"type":"h2","text":"A Better Dining Experience"},{"type":"p","text":"Technology streamlines operations, so customers get a faster and more accurate ordering experience. With QR codes like the personalized one we give merchants who sign up with orderOS, you get a host of features that directly benefit your customers, including"},{"type":"p","text":"1. One-tap and mobile payment options, so guests finish transactions as soon as they’re ready, without having to wait for servers to clear the table and stop by the POS terminal."},{"type":"p","text":"2. Automatically calculate tips, so waitstaff more frequently gets their 20%."},{"type":"p","text":"3. Easily use coupons with QR codes designed to apply discounts at checkout automatically."},{"type":"p","text":"4. Encourage feedback with a code that links to a survey or site for guests to submit reviews."},{"type":"p","text":"5. Make more money on average. Self-service capabilities are historically linked to higher ticket sizes because of personalization bolstered by forced modifiers and no fear of judgment when they supersize that combo."},{"type":"p","text":"While some customers will undoubtedly be resistant to new technology, you can encourage using QR codes with rewards like a first-time discount if they order off the digital menu rather than a third-party service. Connect with customers on social media to forge more comfortable connections and expand the reach of your online marketing efforts."},{"type":"p","text":"to learn more about digital solutions, a branded merchant app, and a smooth transition into the world of off-premise dining. QR codes are designed to maximize your profit at the greatest possible convenience for you. The next era of restaurant management starts with developing smart online ordering solutions and digital tech solutions. It begins with QR codes and all they have to offer."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #OnlineOrdering #RestaurantBusiness #QRCodes #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_13bba45c427a4bf88dbcda3c69a8644e~mv2.png', 'Self-Service Kiosk', 'eatOS Staff', '2021-04-22', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-restaurants-can-join-the-virtual-event-trend', 'How Restaurants Can Join the Virtual Event Trend', 'Photo by Chris Montgomery on Unsplash', '[{"type":"p","text":"Photo by Chris Montgomery on Unsplash"},{"type":"p","text":"The COVID-19 pandemic has shut down most in-person businesses, not just restaurants. Many offices that would regularly order catering or have office events moved to work from home setups. For many restaurants that rely on offices as regular customers, it was a devastating blow but many companies are hosting virtual events to keep morale up during isolation."},{"type":"p","text":"Many other people are desperate for new experiences during isolation. Many foods, alcohol, and music festivals have moved to a digital venue that includes live streaming, curated food and drink as well as personalized meet and greets. Providing experiences to people stuck at home has become a trend any restaurant can take advantage of."},{"type":"p","text":"Heres how your restaurant can capitalize on experiences during the pandemic."},{"type":"h2","text":"Entertainment"},{"type":"p","text":"Live music isnt dead during the pandemic. Many music and food festivals that heavily featured live music have moved to a digital platform. It is possible to pair catering with live-streamed music to create a curated experience similar to a private box concert."},{"type":"p","text":"Many platforms can accommodate private live streams for commercial purposes but a simple place to start is existing video platforms like Zoom, YouTube or Twitch. Coordinated food delivery should also be simple if participants are local or for a wider audience mail-in food kits are also popular options."},{"type":"h2","text":"Cooking Classes and Food/Beverage Tastings"},{"type":"p","text":"An easy way to increase revenue and community engagement is by offering expert cooking classes and tasting. Your staff are already trained professionals that know the ins and outs of your cuisine, this is a perfect way to show off your talents."},{"type":"p","text":"Coordinated food delivery kits via local delivery or by mail are easy ways for customers to get everything they need for a personalized and guided cooking lesson. DIY meal kits have exploded in popularity during the pandemic, but the extra step of a personalized professional makes what would usually be a chore into an experience."},{"type":"p","text":"If your customers dont want to cook, they can learn more about what they love the most. Wines, cheeses, cured meats, liquor and so much more. There is a nearly infinite amount of food that people enjoy and would love to become an amateur expert on!"},{"type":"h2","text":"Advice"},{"type":"p","text":"Zach Geballe is a wine educator for Tom Douglas Restaurants and the owner of Disgorged Wine. Geballe has offered a series of online wine tasting classes throughout the pandemic. He constantly experiments with the medium and has grown a reputation for excellent experiences. Here is what he had to say about virtual events."},{"type":"p","text":"You have to really think about what youre trying to accomplish, Geballe said. Is it entertainment, education, or promotion? All of those will require different approaches. As best as you can, try to figure out who your audience is. I knew that I had to aim at folks who were looking at quarantine as a time to explore their passions. My classes are quite reasonably priced, but they, and the wines that accompany them, are definitely more expensive than many wine drinkers would be interested in, and Im fine with that. I feel very confident that I can deliver a class experience that makes people feel very good about the $25-$35 theyve spent on a 90 minute class."},{"type":"p","text":"Similarly, Maurice DiMarino, who is the beverage manager for Cohn Restaurant Group, has rolled out numerous classes on beer, wine and various spirits. He preaches creativity, fun and new ways to surprise and delight your customers."},{"type":"p","text":"I started out during the shutdown doing Zoom classes with my staff where we covered the history of different spirits, he said. I realized I could repurpose them and tailor them for consumers. Sure, consumers have information at their fingertips with Google, but there is something about tasting and listening to someone talk about the product that they cant get elsewhere. Theyve been blown away by the experience."},{"type":"p","text":"Virtual events increase online business as it is an excellent way for customers who enjoyed their experience can order specific products. If they are local it also increases brand awareness and possible future business."},{"type":"p","text":"Anything they tasted during the classes, I offer for retail sale afterwards, he said. I send everyone a simple Google form where they can place orders for the things they liked. The guests come to one of our designated restaurants to pay and pick up their orders, with many of them ending up eating on the patio or doing take out. It gives guests a reason to come see us."},{"type":"p","text":"#CloudBasedTechnologybyeatOS #Covid19Pandemic #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_00f6096c78ee4c9e9363d7cb89b2566a~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2021-04-20', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-seriously-should-you-take-restaurant-reviews', 'How Seriously Should You Take Restaurant Reviews?', 'For every business, there’s at least one online review published about their services. Restaurants in the modern age can’t escape being talked about on the internet; frankly, no one with a social media page can avoid...', '[{"type":"p","text":"For every business, there’s at least one online review published about their services. Restaurants in the modern age can’t escape being talked about on the internet; frankly, no one with a social media page can avoid that fate."},{"type":"p","text":"As a savvy customer who understands the complicated ins and outs of web posts, restaurant reviews’ value lies in knowing which ones to take seriously and which ones to pay no heed to."},{"type":"h2","text":"Why do people leave reviews?"},{"type":"p","text":"82% of customers read online reviews before they try somewhere new to eat. People trust online reviews as much or even more than suggestions from their friends. Creating a review takes time and, even though it’s only a few minutes out of their day, most customers can’t be bothered to comment on their experiences. That inherently skews any review you read because they had to have a powerful motivator to write their thoughts down in the first place."},{"type":"p","text":"Typically only a few kinds of people leave reviews. They might have been referred by online reviews themselves and want to give back, so to speak; leaving honest feedback about their experience helps paint a more accurate picture for others. Similarly, some people leave suggestions for how the business can improve; these reviews are usually more nuanced with some sense of what went right and wrong to expect more accuracy here. Others might write to archive their own experiences or share them for clout online to gain followers."},{"type":"p","text":"Often people want to leave a quick review of their experience but don’t have the time, patience, or words to express their opinion. Star ratings might hold more weight than the comments’ net energy, so balance that against the quality and quantity of written reviews before deciding which should hold more water."},{"type":"h2","text":"Telling good reviews from bad ones"},{"type":"p","text":"Before you decide which reviews you should pay attention to, you need to know where to look. Websites like Yelp, Google, Tripadvisor, Facebook, OpenTable, and Zagat are great places to start. Of course, there are just as many trolls where there are honest reviews, and you should know how to tell the two apart."},{"type":"p","text":"Take a quick look through their profile and notice if the person has left other reviews, if these are all overwhelmingly positive or negative, or if their comments are relatively generic; all of this might point to a troll, bot, or otherwise fake account. If a profile looks sketchy, focus more on nuanced reviews as these are more likely to reflect an accurate account."},{"type":"p","text":"Sometimes businesses will leave comments thanking users for their reflections, asking how they can improve the experience, and even giving out a direct line to customer service or management. This tells you that those reviews likely hit close to home since the restaurant wanted to directly address the concerns. Occasionally a restaurant will respond unprofessionally or even nastily to online reviews, even to trolls who successfully push their buttons. Although one online interaction doesn’t necessarily dictate the rest of the guest experience, you can still avoid unprofessional establishments that can’t keep their cool by scouring online review sites ahead of time."},{"type":"p","text":"Of course , not all bad reviews are bad news, just as not all good reviews have enough detail to paint a useful picture. Examine the _content_ of each review, not just the general tone or star rating, to know which deserves the full weight of your consideration and which complaints are frivolous, fake, or otherwise not worth your time."},{"type":"p","text":"As a savvy consumer in the internet age, it’s up to you to identify which reviews to give weight to. They hold great power: You’ll consider visiting or avoiding a business because of them. The importance of your favorite restaurants’ reputation may well rest on your shoulders, so if you have the time, consider leaving them a review to let them know how much you appreciate their services."},{"type":"p","text":"#CustomerRelationships #eatOS #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_947d657b093341f59c8ffea48e426333~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2021-04-15', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-technology-is-changing-the-future-of-food-service', 'How Technology Is Changing the Future of Food Service', 'The food service industry is constantly evolving, moving toward restaurant solutions that prioritize efficiency, customer satisfaction and, of course, revenue. Technology, particularly that which incorporates...', '[{"type":"p","text":"The food service industry is constantly evolving, moving toward restaurant solutions that prioritize efficiency, customer satisfaction and, of course, revenue. Technology, particularly that which incorporates automation, is taking over the food service industry and setting the stage for years to come."},{"type":"p","text":"The world is becoming more tech-centric, so it makes sense that small businesses have taken to these trends as well. Restaurants in particular need to keep up with the demands of the market to stay ahead. Increasingly, customers prioritize quickness, safety and quality in their food service, thus inventions are coming out to help any restaurant meet them where they are."},{"type":"h2","text":"What’s so great about technology?"},{"type":"p","text":"Automation concerns some restaurant employees because they don’t want evolving technology to take over their jobs and render them irrelevant: The more a machine can do, the less reason there is to keep a person when the job can be done faster, better and cheaper. However, these fears are baseless; technology doesn’t steal jobs, it provides opportunities to redirect service workers’ energy into other areas of the business which might be deficient and require more hands-on attention."},{"type":"p","text":"Technology also makes it easier to keep track of your restaurant’s data and information. Here’s where a good point of sale technology becomes necessary: View and track inventory, easily advertise promotions and garner data about which sales should go live and when, schedule and manage staff more efficiently, go paperless and even enter data using scannersall from one localized system. Having a data hub like this makes it fast and easy to monitor the progress in different areas of your business and then take control of any situation you want to see changed. Alterations get implemented across every device in your store automatically, so you never have to go offline for updates to take effect."},{"type":"p","text":"It’s important to supplement increased sales by having a functional website, mobile app and social media. Social pages will expand your network and make it easy to connect to potential new customers, who can then navigate to your website for more information or a closer look at your menu. From there, you’ll need to optimize your site and menu for compatibility with multiple devices so that it’s easy for customers to read it on-the-go from their smartphones, since thats where many people decide what to eat. You should consider installing a personalized app for customers to order directly from you, rather than relying on third party delivery platforms which generally charge a high commission fee and force you to relinquish control of the delivery process. Point of sale companies like eatOS will set up apps like that, each tailored for your individual needs, when you sign up with us."},{"type":"p","text":"Self-service devices improve customers’ experiences by making the ordering process faster and more accurate and adjusting ticket sizes up to 30%. In recent years, self-service kiosks have gained a lot of traction, catering to the modern customer, improving productivity and more, all while costing you less. At the same time, AI is taking off. The two services combined can make a big difference on your bottom line."},{"type":"p","text":"Now more than ever, it’s important to prioritize streamlined delivery and contactless services, both off-premise and on. COVID-19 has permanently changed the landscape of the food service industry, and now prioritizing the health and safety of your customers and staff must be the paramount consideration. Flexibility and open-mindedness will help any restaurant train to become a more technology-reliant business."},{"type":"p","text":"Off-premise sales, new marketing tactics and all the other benefits that technology offers are must-haves for any successful business, primarily because these tactics cater to younger generations. That audience lives in a technological world and expects the businesses they patronize to adapt accordingly."},{"type":"p","text":"The world already has technology embedded deeply within it, from how we order a pizza at one in the morning to the way we switch shifts at work. Adapt to changing technological trends to stay relevant in the marketplace and provide a more fulfilling experience for any customer. The restaurant industry is moving, with every other business, toward a more technology-centered world. Get a demo with eatOS today to learn how to bring your restaurant into the future with it."},{"type":"p","text":"#eatOS #RestaurantTechnologyandCOVID19"}]', 'https://static.wixstatic.com/media/a77ed6_985be915b3e14dda81807e3f6afaf70d~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-04-13', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-the-new-covid-19-stimulus-bill-affects-restaurants', 'How the New COVID-19 Stimulus Bill Affects Restaurants', 'Since the first COVID-19 stimulus bill was passed last spring, small businesses all around the U.S. have waited with bated breath for the next round of relief packages to save them from permanent closure. Unfortunately...', '[{"type":"p","text":"Since the first COVID-19 stimulus bill was passed last spring, small businesses all around the U.S. have waited with bated breath for the next round of relief packages to save them from permanent closure. Unfortunately for many now-defunct businesses, help never came, until now."},{"type":"p","text":"In particular, restaurants have been affected by this pandemic’s ups and downs, with mass closures and partial capacity seating causing a $130B loss in revenue from 2019. Congress has discussed a new stimulus bill for a while; many in the hospitality industry were pushing to tackle the Restaurants Act, which would have designated $120B of the relief to small restaurants and bars. To guarantee it went to the right people, the Act would have stipulated that it only applies to restaurants with fewer than twenty locations, with priority given to minority- and women-owned establishments."},{"type":"p","text":"Congress ultimately didn’t include the Restaurants Act in the bill. However, both House Speaker Nancy Pelosi and Senate Minority Leader Charles Schumer announced late Sunday that they made critical changes to the $900B emergency relief package that passed in December. This included modifications to the Paycheck Protection Program targeted at independent restaurants."},{"type":"h2","text":"Targeting Small Business"},{"type":"p","text":"Lobbyists specifically pushed to right some of the wrongs with the first bill, which they felt sent funds to big businesses despite efforts to avoid just that. Many small restaurants didn’t receive the first round of PPP loans, so this time lawmakers specified that it would have to apply to businesses:"},{"type":"p","text":"1. with 300 employees or fewer;"},{"type":"p","text":"2. that experienced a 25% loss in revenue during at least one quarter of 2020 compared to 2019;"},{"type":"p","text":"3. that aren’t publicly traded companies."},{"type":"p","text":"The program has also been extended through March 31st, allowing restaurants that received the first round of PPP loans to reapply. They also changed how they calculate the loan’s size, basically multiplying average payroll costs by a more significant factor. Now each restaurant receives a more generous amount of money to spend, with a maximum loan payout of $2M and still with the potential for some loans to be forgiven, providing recipients spend it appropriately."},{"type":"p","text":"All of this is designed to give the hospitality industry an extra boost because it’s more negatively impacted by the virus, thanks in large part to restrictions on dine-in seating all over the map."},{"type":"h2","text":"More Flexibility"},{"type":"p","text":"Restaurants will get more and more effective, funds and more options about how to spend them. Restaurants have to put 60% to payroll, but the remaining 40% can go to PPE, training, changes to safeguard guests against coronavirus, and perishable foods. The industry was explicitly concerned with the latter; part of why restaurants were hit harder than other small businesses is because even a two-week shutdown in the event of an onsite outbreak is enough to spoil their inventory."},{"type":"p","text":"Businesses covered by PPP will also receive a tax deduction at the end of the business year, so they don’t find themselves with a giant surprise bill. The other NRA and Independent Restaurant Coalition made sure to include this provision to protect restaurants in the second round of a relief bill that seeks to correct the first’s perceived mistakes."},{"type":"p","text":"How the New COVID-19 Stimulus Bill Affects Restaurants"},{"type":"h2","text":"A Brighter Future?"},{"type":"p","text":"In many ways, restaurants are excited about the promised changes; however, many small business owners remain concerned. For example, some smaller restaurants are worried that the funds are being dispersed through banks, though some may not have the financial history or savings available to open an account. Banks big and small are ready to take on the challenge along with authorized credit unions."},{"type":"p","text":"Nonetheless, critics have concerns that even these most crucial changes won’t be enough to save the deep-rooted, coronavirus-related issues hurting the restaurant industry, but it is a start. It seems that with these new provisions, lawmakers are trying to find pragmatic solutions they can include in the emergency relief bill rather than putting it off even longer trying to create a full-fledged, long-term solution. This is the exact reason it’s been put off so long in the first place, and America’s restaurants need a bandaid now, even if it’s not the full-scale shakeup that would genuinely save the industry."},{"type":"p","text":"Restaurants all over the country are excited to see the emergency relief bill provide some help, but we’re all still looking toward the future to see if 2021 will bring the changes they hope for. Only time will tell if this bill provides relief."},{"type":"p","text":"#eatOS #CoronavirusPandemic #Covid19Pandemic #RestaurantBusiness #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_2a79a2e4e30947b5bfe50994f5a90b9e~mv2.jpg', 'Restaurant Growth', 'eatOS Staff', '2021-04-08', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-third-party-delivery-services-are-helping-the-community', 'How Third Party Delivery Services Are Helping the Community', 'With shelter-in-place measures forcing everyone indoors, making people scared to go to the grocery store, and forbidding dine-in services at restaurants across the world, many people have increased how often they order...', '[{"type":"p","text":"With shelter-in-place measures forcing everyone indoors, making people scared to go to the grocery store, and forbidding dine-in services at restaurants across the world, many people have increased how often they order in. As restaurants switch to delivery-only service, many have started partnering with third-party delivery platforms. In turn, these third-party apps have begun working to protect the communities where they operate."},{"type":"p","text":"Many have sent out general notices reminding the public about health and safety measures they should take whenever they get food delivered. These tend to go into detail about specific precautions people should take, such as:"},{"type":"p","text":"1. Wash your hands thoroughly with soap and warm water for twenty seconds. Do this before and after retrieving your items and throwing away their containers, which may have come in contact with people outside."},{"type":"p","text":"2. Disinfect surfaces that touched the bags and boxes after you throw them away. This ensures that your home stays clean and uninfected."},{"type":"p","text":"3. Choose contactless delivery. Pretty much every delivery service right now offers the option to have drivers leave your food at the door and notify you about drop-off via text, call or just by knocking. This prevents face-to-face contact that violates the six foot rule for social distancing."},{"type":"p","text":"Many of these health notices come with additional resources attached so people can support drivers and restaurants directly. For example, Grubhub customers now have the option to round up their change at checkout and donate to the Grubhub Community Relief Fund. The proceeds will go to charities that help local restaurants and drivers who need it."},{"type":"p","text":"Other platforms understand that many customers have lost their jobs and are struggling financially in this crisis. As a result, they’ve waived their delivery fees for many of their merchant partners. Uber Eats takes this a step further: They provide free meals to first responders and healthcare workers, demonstrating their appreciation for the necessary work they do and giving back to them as they take care of everyone in the community."},{"type":"p","text":"Waiving these fees also encourages customers to choose merchants on that app, rather than a competitor who still charges for delivery. This helps local restaurants on those apps get more business. Learn more about how third party delivery platforms are supporting local restaurants here."},{"type":"p","text":"These delivery platforms sacrifice some profit in this time of widespread need so they can help the community and merchant partners that keep them in business."},{"type":"p","text":"Many service providers like eatOS integrate with third party apps like these to keep your restaurant running efficiently. Subscribe with us to learn more about keeping the community safe and healthy."}]', 'https://static.wixstatic.com/media/a77ed6_26ee60fbe6124c459451208cb6bde2ed~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2021-04-06', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-celebrate-fourth-of-july-at-your-restaurant', 'How to Celebrate Fourth of July at Your Restaurant', 'It’s nearly Independence Day, and restaurants all over the country will run special promotions. It’s not just the Fourth of July, but the first big celebration of the summer after a long year of COVID-19. Customers are...', '[{"type":"p","text":"It’s nearly Independence Day, and restaurants all over the country will run special promotions. It’s not just the Fourth of July, but the first big celebration of the summer after a long year of COVID-19. Customers are also excited to kick off the month with the usual festivities. It’s a great chance for restaurants to throw something special and welcome back guests for post-pandemic service."},{"type":"p","text":"Narrow down your niche and focus on what your best customers want out of the holiday. Are you a seafood restaurant? Then try new crab specials. Famous for your steak? Fire up the grill and host a BBQ outside. What matters most is keeping true to your brand and paying attention to your customers’ needs."},{"type":"p","text":"Photo by Tom Dahm on Unsplash"},{"type":"h2","text":"1\\. Kits and Delivery"},{"type":"p","text":"Although you may be open for business, not everyone is up for in-person service yet. Instead, bring a touch of your restaurant to their dinner tables. Meal kits that include special dishes or themed courses are a great draw. Though restaurants are going back to normal this summer, we’re not there yet, so offering contactless alternatives for wary guests can encourage more sales."},{"type":"p","text":"Grill kits let them have their own barbecue with family and friends, too. Alternatively, invite them to join your celebration virtually, as this builds loyalty. Catering kits are also a great offer all year round for any events customers may throw. This is a chance to give them a taste of what you have to offer."},{"type":"h2","text":"2\\. Festive Fourth of July Drinks"},{"type":"p","text":"Create a special cocktail menu for a more lively celebration. Fit this specialty your brand depending on your usual audience, choosing sangria specials or deals on beer depending on what usually sells. These can go great with an outdoor BBQ and firework festivities, or incorporated into other deals and events that you usually host on the Fourth of July, such as bottomless seafood deals. Holiday cocktails always go great with whatever dishes you make."},{"type":"h2","text":"3\\. The Right Restaurant Technology"},{"type":"p","text":"Whether you’re serving up new drink specials or a delicious five-course meal, advanced Point of Sale systems enhance the customer experience. eatOS offers tableside devices so servers or customers punch in their orders right there, where it’s then sent immediately back to the kitchen for prep. This saves time, speeds table turns, and improves order accuracy significantly. You can also include order modifications that account for particular dietary restrictions or other customizations, ensuring much happier guests."},{"type":"h2","text":"4\\. Interactive Fourth of July Celebrations"},{"type":"p","text":"Those who do come to your festivities have been missing out on in-person meetings for over a year. Invite them in for cooking classes where they get to eat the result or have beer tastings where they learn how to pair it with food. Interactive activities are a great incentive to draw in customers this summer."},{"type":"h2","text":"5\\. Consider Restaurant Demographics"},{"type":"p","text":"Born-and-bred Americans aren’t the only ones celebrating freedom. First- and second-generation immigrants are also joining their cultures and homes together. Considering that immigrants make up a significant portion of hospitality workers and 37% of small restaurant owners, lean into the industry’s diversity with cultural dishes that have Americanized twists. There are all kinds of ways to honor your customers and celebrate freedom this Fourth of July, so find ways to make the most of it."},{"type":"p","text":"Photo by sheri silver on Unsplash"},{"type":"h2","text":"Ready Your Restaurant for Fourth of July"},{"type":"p","text":"Now that the day is almost upon us, use these tips as a jumping-off point for whatever works best for your brand. Depending on your customers, regular menu, and atmosphere, different ideas will pull in better business. Smart Point of Sale systems track variations in performance over time, so you can see which promotions worked best in the past and adapt them for the current marketplace."},{"type":"p","text":"#RestaurantMarketing #eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurant #FourthofJuly"}]', 'https://static.wixstatic.com/media/a77ed6_d994d20a5e5740bcbda78ff419a4135b~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2021-04-02', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-create-a-profitable-menu', 'How to Create a Profitable Menu', 'Menus are the restaurant’s most important sales tool. When you invest so much into digital ads or clever promotions, it’s easy to forget that you don’t just rely on drawing people into the restaurant to make a profit....', '[{"type":"p","text":"Menus are the restaurant’s most important sales tool. When you invest so much into digital ads or clever promotions, it’s easy to forget that you don’t just rely on drawing people into the restaurant to make a profit. Your menu works in subtler ways. What makes customers choose one dish over another: Is it the cost? The description? The pictures?"},{"type":"p","text":"Menu engineering evaluates your prices, sales data, and food costs to generate information about which dishes to feature and how to price them. Make smarter choices about what to put on the menu and watch your daily sales grow."},{"type":"h2","text":"Better Menu Management"},{"type":"h2","text":"Engineering Your Menu"},{"type":"p","text":"Invest in a smarter Point of Sale to grow your business more effectively. A good POS collects data from every customer sale, whether it’s online, in-person, or via third-party service. This gives you access to real-time information with automated reports made for your convenience. When you know what dishes sell best, you can create promotions to move even more of that or shed light on items that don’t do so well."},{"type":"p","text":"Streamline both food and drinks for maximum profitability. If your POS indicates a lot of waste, perhaps order less at a time from vendors or raise portions and prices to suit what’s in stock. Also, keep track of food cost percentage to better price out all your options to turn a profit."},{"type":"p","text":"The items themselves also need to seem enticing on the page. Keep descriptions short and to the point so guests don’t have to read too many paragraphs just to find what they want for dinner. Menu engineering capabilities that come with smart POS management features let you organize your items in accordance with where customers look on the page. This subtly sells certain dishes over others. That’s right: Even placement matters."},{"type":"h2","text":"Popularity and Profitability"},{"type":"p","text":"All the choices you make about your menu should be to make every option either profitable, popular, or both. Classify by this metric to determine where on the page you should place an item within its food category (e.g. Sandwiches, Brunch, Seafood, etc.) to improve sales across the board."},{"type":"p","text":"1. Stars are popular and profitable."},{"type":"p","text":"2. Puzzles are profitable but not popular."},{"type":"p","text":"3. Duds are neither popular nor profitable."},{"type":"p","text":"These numbers are a good foundation, but supplement the information gleaned from sales data with real-life anecdotes from guests or customer surveys given at the end of a meal. Even complaints can hold key information to help you grow."},{"type":"h2","text":"Best Practices"},{"type":"p","text":"For the most accurate analysis, choose a specific time frame to track. For example, if you rotate out menus depending on what ingredients are growing locally, then analyze sales trends seasonally. If you don’t tend to change with the seasons, track growth and profit margin by quarter to get the best grasp on your business’s health."},{"type":"p","text":"Find what works with both your printed and digital menu. Too many items on a page can overwhelm the eye while too many sales categories overcomplicates it. Meanwhile, customers don’t like having too many options; the burden of choice gives you good reason to pare out duds."},{"type":"p","text":"Photo courtesy of eatOS."},{"type":"p","text":"Once you settle on positive changes, monitor the results to ensure continued upwards growth. Train your staff on the new menu so they work with subliminal and outright sales tools to upsell whatever promotion you’re pushing next."}]', 'https://static.wixstatic.com/media/a77ed6_d741aa7ce9e244c3bff9d7f9e2f2cafb~mv2.jpeg', 'Inventory Management', 'eatOS Staff', '2021-03-31', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-create-an-experiential-restaurant', 'How to Create an Experiential Restaurant', 'Your restaurant is your baby, but its hard work to make it matter to your intended audience the way it matters to you. More and more, customers crave a unique restaurant experience; “eatertainment,” or experimental...', '[{"type":"p","text":"Your restaurant is your baby, but its hard work to make it matter to your intended audience the way it matters to you. More and more, customers crave a unique restaurant experience; “eatertainment,” or experimental concepts that breathe excitement into plain old dinner."},{"type":"p","text":"75% of Millennials prefer an interesting, all-encompassing experience to just enjoying good food; although that can mean anything from a dinner show to games to anything else that turns the regular restaurant experience into something more entertaining. It’s become an increasingly popular trend in recent years. If your restaurant is looking to add a little spark to its meals, there are a few just things to keep in mind before you launch an experiential, entertaining restaurant concept."},{"type":"h2","text":"Sustainability"},{"type":"p","text":"While searching for the next big hit, keep in mind that Millennials and all your other customers have certain values which you need to prioritize as much as you need to cater to their enjoyment in order to become relevant and remain a worthwhile haunt for them to spend their hard-earned time and money. Sustainability is one such factor; consumer trends increasingly favor eco-friendly restaurants that treat employees with respect, among other things. Emphasize your commitment to doing good and watch your customers grow more loyal as a result."},{"type":"p","text":"When building a conceptual restaurant, take advantage of everything you have at your disposal: If your location is well-suited for foot traffic or you have good curb appeal, lean on those advantages with storefront advertising. Take time to find your niche, explore your advantages and then exploit them into a successful experiential concept."},{"type":"h2","text":"Themes"},{"type":"p","text":"People enjoy a good time, a break from their day-to-day lives, no matter how brief. Sometimes, the sillier the better. Take advantage of the space in your restaurant and play around with the decor, the design or even consider putting on some themed events to add something extra to the atmosphere."},{"type":"p","text":"If you are going to put on some sort of “experience, be it dinner theater or something else, make sure it starts from the second that customers walk in the door so as to really make the most of it. Staff should stay in character from the greeting to the customers’ exit to get the fully immersive experience. Get creative and make it unique if you want to really outsell your competition."},{"type":"h2","text":"Community"},{"type":"p","text":"It’s good to come together to eat; people crave it, and it’s a tradition as old as time. Studies show 69% of Millennials like to dine out partially as a reason to connect with friends, family and people in general. Experiential dining is a great way to encourage these connections: Drive toward a common goal, or enjoy a show together, or something of the sort."},{"type":"p","text":"A creative restaurant concept is a chance to cultivate a space where people are encouraged to come together. Drinks, food and activities invite interconnectivity with little distraction, and that will lead customers to take a night off now and then to come back to your restaurant with their favorite people."},{"type":"h2","text":"Appeal"},{"type":"p","text":"For the best restaurant experience, of course, you need to take just as much care with the _restaurant_ aspect as you do the _experience_. Neither should be sacrificed, even a little, for the other. Appeal to all the senses: Sight, smell and taste especially, though the other two shouldn’t get left by the wayside. All of this will draw customers in and make them want to come back for more."},{"type":"p","text":"77% of customers find food one of the most important aspects of any event, so it’s safe to assume that goes at least double for your restauranteven an experiential one. You can trim your menu down to focus on the more lively aspects of this particular business but the food needs to be just as compelling as the fanfare or folks will find something else to entertain them on their nights off. Remember, you’re trying to push the envelope of traditional food service…but it’s still food service."},{"type":"p","text":"Yes, creative experiential restaurants are the big up-and-comers of the hospitality industry. It’s not the only new trend, though, and you can incorporate other popular facets into your concept to really make it shine. Technology, for example, is increasingly being used to deepen customers’ experiences too. If you can integrate that into your concept then it’s more likely to succeed, and continue succeeding exponentially over time. Convenience and speed are also majorly important for consumers, so emphasize these factors too if it works for your business."},{"type":"p","text":"The blessing of an experiential concept is that you can, well, experiment. Find what works for you, draw in your targeted customer base and then hit the ground running in that direction. Eatertainment is a vastly unexplored but massively profitable industry, so get in while the getting’s good."},{"type":"p","text":"#eatOS #RestaurantBusiness #RestaurantMarketing #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_03d59e119c404b60ba251de56c4d3dec~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2021-03-26', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-improve-employee-productivity-in-your-restaurant', 'How to Improve Employee Productivity in Your Restaurant', 'Restaurants rely on the efficiency and productivity of every employee, working together to create a seamless dining experience for each guest who sits down or takes out. Your servers are the face of the business, the...', '[{"type":"p","text":"Restaurants rely on the efficiency and productivity of every employee, working together to create a seamless dining experience for each guest who sits down or takes out. Your servers are the face of the business, the go-between for the brand and the world. In a fast-paced environment of a restaurant, you need the best of the best workers who can handle the daily stresses of a demanding job."},{"type":"p","text":"As a boss and mentor, restaurant managers have to not just organize their underlings but encourage their success by whatever means works best for that individual. Everyone’s different. How can you make your employees happier and more productive to ensure the continued wellness of your restaurant business?"},{"type":"h2","text":"Happy Workers, Happy Eating"},{"type":"p","text":"When they’re given breaks to rest, the right training for seamless activity, and the tools they need for their positions, the biggest barrier to employee success is a lack of motivation and satisfaction. Keep their spirits up and infectiously good attitudes will spread to your customers too."},{"type":"p","text":"1. Nothing improves morale like good compensation; rewards and bonuses are hard to beat and the easiest way to improve productivity. Whether by increasing the minimum wage, giving small gestures of thanks to hard workers or holding outright sales contests to gift winners with a free dinner, find small ways to show your appreciation."},{"type":"p","text":"2. Avoid burnout by alternately assigning overnight and weekend shifts that nobody wants to take."},{"type":"p","text":"3. Offer free food and drinks during breaks, or at least a special employee discount on the menu. Give coworkers something to bond over and make them better acquainted with the menu so they can genuinely recommend dishes to new customers."},{"type":"p","text":"4. Improve communication and feedback to smooth interactions between the front and back of house and avoid common mistakes. Talk to your employees to see what they need to be more successful at their jobs. Listen to guest feedback as well to learn what areas your best customers find deficient and how you can improve to foster better customer relations and loyalty."},{"type":"p","text":"5. Manage coworker relations to avoid blowouts. When potentially different personalities work in close quarters together, friction naturally occurs. Everyone should feel safe and secure so they can put their best foot forward, which won’t happen if they’re nervous about coming into work. Incorporate icebreakers and conflict resolution tactics into orientation so everyone is equipped to tackle arguments that crop up and will greet each day professionally and ready to work."},{"type":"p","text":"6. Provide a safe workplace for all. Make sure you’re OSHA compliant; no need for an untimely kitchen accident to send operations into a tailspin. Set up an HR department as well to ensure your employees have somewhere to turn that’s on their side."},{"type":"p","text":"Creating a safe, inclusive workplace that promotes individual skill sets and provides the tools your employees need to thrive on the job. Of course, productivity works best when paired with state-of-the-art technological breakthroughs that speed up operations and provide seamless communication between the front and back of the house. eatOS Point of Sale offers self-service devices as part of its network of options designed to improve your restaurant management system."},{"type":"p","text":"We also offer workforce management (WFM) features to manage your employees more effectively. Track their progress overtime and figure out which superstars are driving the most success so you know who to thank when the time comes for raises and promotions. eatOS integration with 7Shifts makes scheduling quicker and easier than ever, while our Gusto partnership automates payroll for you too."},{"type":"p","text":"Workers want to feel valued and respected in their place of work. Show them that their voice matters and teach them important skills that will guide their success throughout their entire restaurant career. Productivity starts from the top down; the best bosses are also mentors who show employees the right attitude to guide their success and lead by example. Give back to your workers the best way you can, by providing them invaluable lessons that they can take with them into the future."},{"type":"p","text":"Combine superior PoS technology with personal motivation and watch your employees thrive. eatOS makes restaurant management easy. Book a demo today to learn how we’ll help bring your restaurant into the future of food service."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurant #WorkforceManagement #StaffingampRecruiting"}]', 'https://static.wixstatic.com/media/a77ed6_cdb3d0ae185744908cd781a231a53469~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-03-24', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-improve-staff-communication', 'How to Improve Staff Communication', 'The restaurant industry wants to improve employee satisfaction and retention. Turnover in the industry is famously rampant, and they’re experiencing a labor shortage right now because of COVID-19. All of this affects...', '[{"type":"p","text":"The restaurant industry wants to improve employee satisfaction and retention. Turnover in the industry is famously rampant, and they’re experiencing a labor shortage right now because of COVID-19. All of this affects the productivity of those still employed. To solve this tangled web of problems, restaurants are looking at improving their staff communication."},{"type":"p","text":"Employees who like each other, work more effectively together, especially during a stressful rush. Better relationships also encourage workers to stick around, since it’s hard to find a job they enjoy where they work with friends."},{"type":"p","text":"Unfortunately, obstacles remain in place that make inter-staff communication more difficult. Fewer workers means having to spread them out across shifts. This combined with constant turnover makes it difficult for them to form relationships deep enough to bolster productivity. Hopefully as the pandemic winds down, restaurants can begin reform for long-term, effective staff communication."},{"type":"h2","text":"Types of Staff Communication"},{"type":"p","text":"Photo by Ketut Subiyanto from Pexels"},{"type":"h2","text":"Management to Employee"},{"type":"p","text":"Open dialogue between every level of the hierarchy shows that the business really cares about what its employees have to say, which improves retention. Check-in, not just about their job performance, but also to make sure their mental health is fine too. Show you care about them as people, not just workers, and they’ll try harder and stick around longer."},{"type":"p","text":"Regular staff meetings will also benefit everyone. There, employees can address any concerns they have and solve workplace problems as a team. Meanwhile, their individual evaluations should also incorporate questions about their interpersonal skills. Instead of only having a once-in-a-while performance review, schedule them more frequently and use it to highlight what they’re doing well, too. Taking a more holistic approach to workforce management sets the foundation for continued success moving forward."},{"type":"h2","text":"Employee to Employee"},{"type":"p","text":"Since it’s so important for the team to work together, set aside time specifically for them to get to know each other more deeply. Maybe you set up regular team lunches on a slow day, or some other team-building exercises to get their guards down without the pressure of management."},{"type":"p","text":"Create opportunities for them to get together off-premises, too, as this will relieve any extra pressure from being under the eyes of their employer. They’re more likely to get closer this way, which again relates to retention and overall productivity."},{"type":"h2","text":"Technology Streamlines Staff Communication"},{"type":"p","text":"Upgrading your restaurant systems to include the latest tech on the market will improve communication across the board. Make use of…"},{"type":"p","text":"1. online logbooks to keep track of workforce management notes."},{"type":"p","text":"2. setting individual permissions, for example giving managers access to logbook notes but not servers or cooks."},{"type":"p","text":"3. scheduling software that easily keeps shifts together so they have the chance to get more familiar."},{"type":"p","text":"4. an all-in-one hub to view sales and performance data over time."},{"type":"p","text":"When you digitize training, they can get comfortable on the devices they’ll be using on the day-to-day too. Create staff profiles that have special dates like birthdays, as well as time-off allowances and permissions so you can control what they see on the devices. Save your personal information and bring your employees together with better restaurant technology."},{"type":"p","text":"#Staffing #eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurant #WorkforceManagement"}]', 'https://static.wixstatic.com/media/a77ed6_9687106ceb3249e7ae04a2cdb5f85179~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-03-19', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-improve-your-restaurant-with-customer-surveys', 'How to Improve Your Restaurant with Customer Surveys', 'Every guest who comes into your restaurant should have the same incredible experience that you set out to give them. But how can you really know what customers want or expect, and how can you be sure that they’re having...', '[{"type":"p","text":"Every guest who comes into your restaurant should have the same incredible experience that you set out to give them. But how can you really know what customers want or expect, and how can you be sure that they’re having the time that you hope they have? The easiest way to be sure of all this is to simply ask them."},{"type":"p","text":"Guest feedback reveals the difference between how you think your operations work versus how they actually come off to the consumer. You may think you’re making the smartest business decisions only to find that your most loyal customers actually want something different. Survey questions put the power of change into their hands by letting them choose and convey what’s important to them, so you know exactly how to satisfy your customers."},{"type":"h2","text":"How do you get feedback?"},{"type":"p","text":"There are different avenues for inviting customer feedback after a meal. Some restaurants include a web link at the bottom of the receipt where customers can fill out a survey from home, and you can program some self-service devices to prompt a quick survey after the transaction goes through automatically."},{"type":"p","text":"Still, you need to ask the right questions. Tailor your surveys to shed light on your strengths and weaknesses, but be careful: People don’t want to fill out long questionnaires, and two- or three-part questions will likely result in them skipping it altogether. Use a mix of multiple choice, yes or no, and open-ended questions so the survey doesn’t feel tedious."},{"type":"p","text":"Understandably, youll want to ask them everything about how to improve your business, which makes paring down difficult. Just because you can’t dump everything into one survey doesn’t mean you can’t get all the answers you crave. Rather, rotate out your questions so each guest gives a few vital answers, and multiple surveys come together to give you a fuller picture of the effectiveness of your service."},{"type":"p","text":"Now, you need to figure out what you want to ask in order to hone in on your restaurants strengths and weaknesses."},{"type":"h2","text":"What should you ask?"},{"type":"p","text":"The most important questions to ask at the top of every customer survey is: What was the best part of your visit? What was the worst?"},{"type":"p","text":"These are the most crucial because they cut right to the heart of customers’ expectations, and whether you’ve failed or succeeded to meet them. You can split the remainder of your questions into a few categories to make sure you’re hitting the rest of the bases."},{"type":"h2","text":"General"},{"type":"p","text":"These are the preliminary queries that tell you a bit about the customers themselves."},{"type":"p","text":"1. How did you hear about us?"},{"type":"p","text":"2. Is this your first visit? If not, how often do you come by?"},{"type":"p","text":"3. What’s the likelihood that you’ll return?"},{"type":"p","text":"4. Would you recommend this restaurant to friends? If not, why?"},{"type":"p","text":"5. Is the facility disability-accessible and accommodating?"},{"type":"p","text":"6. Were you comfortable?"},{"type":"p","text":"7. Were the bathrooms and facilities clean?"},{"type":"p","text":"You can also use this part to ask if they think your hours are amenable, if they found the restaurant family-friendly, how far they traveled to come here, if they’re here for any special occasion or if they’re open to any new ideas that you’re considering. If you’re debating a wine list, reservation system or adding something special to the menu, run it by some customers first and get an idea what they like. You can even ask them about the music and ambience if you’re really inclined to tailor the experience to as many guests as possible."},{"type":"h2","text":"Food and Drink"},{"type":"p","text":"Here’s where you can get more in-depth about your products."},{"type":"p","text":"1. Rate the food. (Use a 1-5 scale or whichever metric you prefer.)"},{"type":"p","text":"2. Were the drinks satisfactory?"},{"type":"p","text":"3. Was there something you wanted to order that wasn’t on the menu?"},{"type":"p","text":"4. Did everyone in your party find something they wanted?"},{"type":"p","text":"5. Rate the range of menu options."},{"type":"p","text":"6. Were all dietary restrictions met and handled to your satisfaction?"},{"type":"p","text":"If there’s anything else you want to know, like specific feedback on a new dish you’re trying out, then now is the time to dig deep into customers’ individual opinions on matters like that."},{"type":"h2","text":"Service"},{"type":"p","text":"Rank the competency and effectiveness of your workers so you can streamline labor costs and manage your workforce to optimal efficiency."},{"type":"p","text":"1. How was your server? Were they friendly and accommodating?"},{"type":"p","text":"2. Did the food come out quickly?"},{"type":"p","text":"3. Was it served to your expectations and liking?"},{"type":"p","text":"4. Did you experience any issues during your visit, and if so, did your server handle it well?"},{"type":"p","text":"These questions will help you hone in on your most, and least, hardworking employees so you have more information when it comes to writing up employee reviews, determining promotions and pay, and seeing which areas of the business the team needs more training on. These questions help trim away the fat so you’re left with the best of the best."},{"type":"h2","text":"Technology"},{"type":"p","text":"Tech is such a critically important component of modern restaurants that you don’t want to neglect it in your assessment of the customer experience. You want to make sure that it’s working correctly but also that customers find all these devices easy to operate and understand."},{"type":"p","text":"1. Was checkout efficient?"},{"type":"p","text":"2. Was the kiosk easy to use? Why or why not?"},{"type":"p","text":"3. If you ordered online, how quickly did your food arrive? Was it presentable and to your satisfaction?"},{"type":"p","text":"4. Which online provider did you use (if you have your own delivery platform and also partner with third party services)?"},{"type":"p","text":"5. Did you use a discount or promo code?"},{"type":"p","text":"6. Are you part of our loyalty program? If not, would you like to join?"},{"type":"p","text":"Advanced Point of Sale systems, like the one powered by eatOS, integrate questions like these directly into the checkout experience so it’s the natural conclusion to every meal. You can automatically prompt the survey on receipts, over text or email, or during checkout so youre sure to get feedback from all your customers equally, not just the ones who are already loyal."},{"type":"p","text":"Survey questions are one of the most important metrics for determining guest satisfaction and managing customer relationships. Working to optimal efficiency means meeting and exceeding expectations wherever possible. Schedule a demo with eatOS to learn more about how our Point of Sale makes every aspect of the customer experience a breeze."},{"type":"p","text":"#eatOS #CustomerExperienceisitmatter #RestaurantBusiness #CustomerFeedback #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_6be341fd3a8b4905afd88ed9f511995a~mv2.jpeg', 'Self-Service Kiosk', 'eatOS Staff', '2021-03-17', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-make-your-restaurant-disability-friendly', 'How to Make Your Restaurant Disability-Friendly', 'Getting ready to open a new restaurant is a serious endeavor, and there’s a lot to take into consideration: From the menu to the floor plan to your targeted demographic, owners have their plates full building a business...', '[{"type":"p","text":"Getting ready to open a new restaurant is a serious endeavor, and there’s a lot to take into consideration: From the menu to the floor plan to your targeted demographic, owners have their plates full building a business from the ground up. Unfortunately, during all the decisions about which flooring to use and how many tables you can fit inside, a lot of owners don’t consider the needs of disabled customers and how appropriate accommodations affect everything from the width of your walkway to the lettering on the menu."},{"type":"p","text":"Disability accommodations should be built into the foundations of your restaurant to ensure it’s accessible to all customers from day one. After all, it’s harder to make massive structural changes once things are already set down. The 2019 Census Bureau reported that 12.7% of people have a disability that significantly impacts their day-to-day activities; that’s more than one out of every ten customers coming into your store."},{"type":"p","text":"To help you better cater to guests and ensure that everyone who visits has a high-quality experience, we’ve assembled these tips for building a more equitable restaurant experience. Though this is by no means comprehensive, it’s a good starter guide for any restaurant to hit the ground running."},{"type":"h2","text":"Self-Service Technology"},{"type":"p","text":"Thankfully, advancing restaurant technology means that many devices now come with built-in disability accommodations. Its all a matter of choosing the right service provider; dont be afraid to shop around for one who has exactly what youre looking for at an affordable price."},{"type":"p","text":"One clear indicator of why it’s so important to have disability-accessible technology is the lawsuit against Dominos Pizza from last year: A blind customer sued them for failing to equip their app and website with appropriate accommodations, and he won. It’s not only ethical but financially and legally sound, to comply with disability regulations set out by the Americans with Disabilities Act (or ADA)."},{"type":"p","text":"Let’s take the self-service kiosk as an example, particularly because it’s one of the pinnacles of how advanced technology can improve restaurant operations and increase profits immediately. Many restaurants have found them especially advantageous when it comes to customer satisfaction and increased check sizes; for more reasons why self-service kiosks are so critical for businesses and to find out why so many are jumping on the trend, check out this article on the benefits of self-service."},{"type":"p","text":"They can be equally useful when they’re equipped with ADA-compliant accessibilities. Follow regulations by setting up kiosks like so:"},{"type":"p","text":"1. Have clear access from both the front and sides of the kiosks so it’s easily reachable from any angle."},{"type":"p","text":"2. Interactive controls must be between 15 - 48” above the floor to make them accessible to people in wheelchairs. This includes the touchscreen, keyboard, and any other controllable aspects of the device."},{"type":"p","text":"3. There are additional height regulations if either front or side access is blocked, for example, interactive controls can be set back up to 25” depending on the height of the blockage. Check the ADA website for specifics because they vary depending on the height and width of the obstacle as well as where the block is situated."},{"type":"p","text":"4. Design a clear path to the kiosk. Just because you have room to stand in front of or to the side of it, doesn’t mean it’s easily accessible especially for customers who may have visual or motor disabilities."},{"type":"p","text":"5. Equip self-service technology with various audio options for people who may be visually or hearing impaired."},{"type":"p","text":"When choosing technology for your restaurant, remember that “self-service” should be equally accessible for everyone. Customers with disabilities should have an equitable experience with these devices as any able-bodied customer. Remember that impairments don’t only involve wheelchairs, but that there are a wide variety of visible and invisible disabilities which deserve equal consideration and respect."},{"type":"p","text":"Failing to comply with ADA guidelines means potentially overlooking 35M customers. In addition to being illegal, it’s plainly bad business. Your restaurant should be ready to handle every customer fairly and ensure their experiences are quality and respectful. Self-service accessibility for all means giving disabled customers a comparable experience to abled users, with access to self-service and suitable technological accommodations."},{"type":"p","text":"Implement devices like this, as well as others that suit your restaurant’s specific needs, as soon as today. Browse eatOS products to find self-service kiosks and other advanced technology that fits your needs."},{"type":"h2","text":"Design"},{"type":"p","text":"Creating a disability-friendly environment isn’t just about the technology you use; it starts from the ground up. The layout and design of the restaurant itself needs to accommodate all customers too."},{"type":"p","text":"Sometimes seemingly-innocuous choices can have unexpected consequences. For example, have you ever considered the noise level in your restaurant? Loud, ambient music and open kitchens have their own benefits, but it can make your restaurant inaccessible to customers who have hearing problems that make it difficult to regulate noise in the same way as able-bodied customers. Handicapped parking and big bathroom stalls with handrails that meet the minimum requirements laid out by the ADA may seem like a no-brainer, but the bare minimum isn’t always comfortable to maneuver. Of course, you need a wheelchair ramp if your entrance is up a set of stairs, and your aisles should be wide enough to fit mobility assistance devices, but have you considered that the minimum requirements still make it difficult not to bump into chairs and other patrons? Does your carpeted floor look nice, but make it unnecessarily difficult to roll a wheelchair? Maybe it’s time to lay down different flooring, or even demarcate the dining area from the queue by laying down tile for one section and wood for another."},{"type":"p","text":"These are all things to consider when designing your restaurant, and it doesn’t stop there. You should also think about:"},{"type":"p","text":"1. Printing menus and food labels in large, high-contrast print so that theyre easy to read. Remember, it’s not only visual impairments that can make it difficult to understand small, dark print. Here’s a starter list of good fonts to use that make it easier for visually impaired, dyslexic, or otherwise disabled customers to read what’s on the menu. Keeping a small flashlight or pair of reading glasses upfront at the host stand can also go a long way for any struggling customer."},{"type":"p","text":"2. Just like alternative menus with allergen and nutrition information, you should print menus in braille for blind customers to use. Of course, servers will still fill in the gaps by listing the specials and answering other questions that might arise, but every customer should be able to dine with you under their own power."},{"type":"p","text":"3. To that end, you should consider printing out an allergen and nutrition menu in braille too. Anyone can have a restricted diet."},{"type":"p","text":"4. Consider keeping audio menus on hand for people to request whenever necessary."},{"type":"p","text":"5. Post signs in braille too, anywhere customers or staff might go. Bathrooms, pickup windows, the kitchen, and anywhere else that already has posted signage should have those same directives in braille."},{"type":"p","text":"This is by no means a comprehensive list of disability accommodations, but rather a starting point that demonstrates how ableist ideas are so deeply ingrained that we tend to look past all the little ways that something as simple as flooring can significantly impact a disabled customer’s experience, for good or for bad."},{"type":"h2","text":"Staff"},{"type":"p","text":"Your employees should all have sensitivity training so that they’re not caught off guard when a disabled customer inevitably dines out with you. Sometimes people try so hard to treat people equitably that they inadvertently make the customer feel othered, burdensome or infantilized. Staff should know how to assist disabled customers, such as by rearranging chairs or tables, holding doors, and offering help, without judgment or ridiculeeven accidentally."},{"type":"p","text":"Some pointers for your staff may include:"},{"type":"p","text":"1. Walking them through how a disability might affect different aspects of the environment and experience, so they’ll be able to identify when and how they’re needed for extra assistance."},{"type":"p","text":"2. Exhibiting patience and understanding toward people who have disabilities that are less widely known or accepted. Rather than offering too much or too little help, employees can stay close by so they’re ready to approach if the customer asks for them first."},{"type":"p","text":"3. Always offering straws even if it’s policy not to give one to everybody, as some customers have difficulty without one and others simply prefer it. Bendy straws work best here."},{"type":"p","text":"4. Facing hearing-impaired individuals head-on so they can more easily lipread."},{"type":"p","text":"5. Communicating everything they do so as not to make things more difficult for visually-impaired customers. For example, whisking away plates and glasses without asking can add unnecessary stress when they cant clearly see what youre doing."},{"type":"p","text":"6. Training on every function of the restaurant, including disability assistance technology so that theyre able to adjust or otherwise help disabled customers use the devices and accommodations created for them when they have difficulty. Just as your staff should be able to troubleshoot the self-service kiosk’s traditional functions, they should be able to assist with audio, visual, and motor aids too."},{"type":"p","text":"7. Reminding them that disabilities can be visible or invisible, and no one has to “prove” that they’re disabled “enough” in order to get extra assistance. Believe disabled customers, because they know their condition the best."},{"type":"p","text":"8. When it comes to service animals, staff may ask if the animal is required and what work it’s trained to perform, but anything else is invasive and unnecessary. Furthermore, never interact with a service animal without its owners permission. Some people will be gratified if you offer the animal water or a treat, but always ask first and don’t be offended if they say no."},{"type":"p","text":"9. Diversify your staff to include disabled individuals, but dont put the burden of sensitivity training on your disabled employees."},{"type":"p","text":"A well-prepared staff is less likely to make mistakes or accidentally alienate customers when they’re really just trying to help. No one should feel unwelcome at your restaurant, even by a well-meaning accident. Perhaps it feels as though it should go without saying, but employees should treat disabled customers just like able-bodied customers; be aware that extra assistance may be needed, but don’t infantilize them by acting as though they’re helpless or can’t assert their own boundaries. Sensitivity training will ensure your staff is prepared to give every customer a worry-free, accessible restaurant experience."},{"type":"p","text":"Although ADA compliance is absolutely necessary from a legal perspective, it also has positive effects for your business overall. Equitable service for disabled customers is sadly more of an anomaly than one might expect. The expenses of disability accommodation are offset by greater customer loyalty because they know they can expect high-quality service; unfortunately, many restaurants just don’t offer equitable service for disabled customers."},{"type":"p","text":"Remember, everyone likes self-service and self-sufficiency for the same reasons: It’s quick, accurate, and lets them have a guilt-free, pleasant restaurant experience. Self-service and contactless service doesn’t only mean a high-quality experience for _some_ exceptional restaurant management means ensuring outstanding, equitable service for _all_."},{"type":"p","text":"#SmallBusiness #QSR #CloudBasedTechnologybyeatOS #SelfServiceKiosks #RestaurantTechnologyandCOVID19 #eatOS #SelfService #Brewery #CloudTechnology #Restaurants #Cafe #Technology #FoodServiceTechnologybyeatOS"}]', 'https://static.wixstatic.com/media/a77ed6_d16946c863d84831918a31a32d522a5d~mv2.jpeg', 'Restaurant Insights', 'eatOS Staff', '2021-03-12', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-make-your-restaurant-stand-out-from-the-competition', 'How to Make Your Restaurant Stand Out From the Competition', 'Everyone loves going out to eat. Treating yourself to one of a wide range of cuisines can make a long day or week worthwhile. Where there’s demand, supply will followso it’s no surprise that the marketplace has spawned...', '[{"type":"p","text":"Everyone loves going out to eat. Treating yourself to one of a wide range of cuisines can make a long day or week worthwhile. Where there’s demand, supply will followso it’s no surprise that the marketplace has spawned a host of restaurants to choose between. While this is a blessing for customers, it makes for some pretty harsh competition."},{"type":"p","text":"One out of five restaurateurs cites a flooded marketplace as one of the biggest challenges they face. As a small business owner, you need to leverage everything in your arsenal to stand out from competitors. Most customers don’t have a clear idea of what they want for dinner before they start shopping around, so success hinges on finding what makes you special and developing a marketing strategy around it."},{"type":"h2","text":"Finding Your Appeal"},{"type":"p","text":"To find out what separates you from the crowd, assess each aspect of your business and make a concerted effort to emphasize your most distinguishing features."},{"type":"h2","text":"Identify Your Target Audience"},{"type":"p","text":"First and foremost, you need to identify who you want to attract to your business. Then find your customer persona, too. A customer persona details the demographic profile of your most frequent guests, i.e. college students or businesspeople? Families or couples? If you’re like most restaurants, you’ll have several customer personas, but identify your top three most frequent customer types that you see. Ask your employees for help, since they’re on the front lines and can best identify your regulars, those best and most loyal guests."},{"type":"h2","text":"Narrow Down the Competition"},{"type":"p","text":"Your competitor pool may be larger or smaller than you think. By figuring out how your best customers get to your restaurant, you can determine what other choices they passed over to find you."},{"type":"p","text":"1. Track their digital footprint. What keywords are customers using to find you online? Are they searching for you by your cuisine, most popular dish, or dining style? When you know how customers found out about you, you can find your competitors by looking up the same keywords and seeing who else comes up in the same search."},{"type":"p","text":"2. Identify how your customers get to you. If it’s mainly foot traffic, search within a mile. If you’re near public transport lines, search for the closest bus stops and train stations. If they come by car, search within a ten-mile radius. When you know _how_ people get to you, you can see who else is situated nearby."},{"type":"p","text":"When you know which restaurants your customers passed over to get to you, you can optimize your own operations more effectively to give yourself an edgenow that you understand who it is you’re trying to get an edge over."},{"type":"h2","text":"Find Core Competencies"},{"type":"p","text":"Once you understand the audience you’re appealing to and the competition you need to beat, identify the distinguishing features that make you stand out from the crowd. Your core competencies are what make you special. Is it your ambiance? Your prices? The range and taste of your menu?"},{"type":"h2","text":"Strengthening Your Appeal"},{"type":"p","text":"If you can’t immediately identify what makes you stand out from your competitors, then develop a unique brand for yourself. Brainstorm and develop something unique to use in your marketing copy. Here are some ideas to get started:"},{"type":"p","text":"1. Create an inviting atmosphere with nice decorations or a pretty view. Invite more foot traffic by putting art, your logo or even some flowers in the window that people can see from the street."},{"type":"p","text":"2. Revitalize your patio section or outdoor seating area so it looks attractive from the outside. Post pictures on your social media to broadcast the set-up and entice customers to come see it in person."},{"type":"p","text":"3. Craft a delicious drinks menu! Everybody loves a good happy hour special; make or import craft beers, local wines or new cocktails for guests to try with their meals."},{"type":"p","text":"4. Presentation matters. Even the most generic dish on the menu will seem extra appealing if it’s plated and served in an unusual, interesting manner."},{"type":"p","text":"5. Great staff makes or breaks the experience. Curating top-quality candidates through the interview process will lower your overall turnover rates and make for a better customer experience every time. Read more about how to hire a great staff."},{"type":"p","text":"Make use of technology too. Now, the most advanced devices on the market make it easy to manage and control a lot of these nebulous factors. Track and analyze sales data, guest surveys, staff performance, and more when you sign on for any of our eatOS devices. Get a demo today and let us help your restaurant stand out and really make an impression."},{"type":"p","text":"#eatOS #RestaurantManagement"}]', 'https://static.wixstatic.com/media/a77ed6_a506ed0f9cb4416d81d9136822c475bf~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-03-10', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-manage-your-restaurant-s-cash-flow', 'How to Manage Your Restaurant’s Cash Flow', 'Cash flow determines so much about how you run your business: It determines your budget, your opportunity for improvement, the interest of potential investors, and ultimately determines your restaurant’s growth...', '[{"type":"p","text":"Cash flow determines so much about how you run your business: It determines your budget, your opportunity for improvement, the interest of potential investors, and ultimately determines your restaurant’s growth potential."},{"type":"p","text":"Cash flow has such a big impact on your day-to-day and overall operations that it’s imperative to understand how it works, how to calculate it and how to adjust it if you don’t like the current numbers. The simple formula is:"},{"type":"h2","text":"Total Cash Flow = Cash Inflow - Cash Outflow"},{"type":"p","text":"Still confusing? Let’s break it down."},{"type":"h2","text":"Inflow and Outflow"},{"type":"p","text":"Your inflow is all of the money you receive during a specific accounting period. This includes your normal operational revenuefood and drink salesas well as any merchandise or pantry items you sell, revenue from catering or hosting events, loans, and any other income you’ve received during this period."},{"type":"p","text":"Your outflow is the opposite: All the operational costs you’ve incurred. This includes loans you’ve paid off, business assets you’ve bought, rent, utilities, payroll, inventory, furniture and supplies for the restaurant, appliances, and anything else you’ve spent money on this period."},{"type":"p","text":"These arent the only numbers to keep in mind; get a handle on your operating cash flow too. It’s not the same as your total cash flow because it doesn’t take outside income into account, instead using only the inflow from normal operations, like food and beverage sales. By ignoring outside income, like loans, you’ll have a clearer idea of your restaurant’s self-sustainability which tells you how you’re really doing. This gives you an idea of how necessary it is to cut down on outflow or increase your inflow. It’s important to be as self-reliant as you can."},{"type":"p","text":"Be meticulous and keep track of sales and spending when they occur, so you have an easier time calculating cash flow later. Restaurant technology has advanced to the point where Point of Sale systems can track and analyze a lot of this data for you, all localized on one smart hub so you can take a lot of the manual math out of the equation. Schedule a demo with eatOS to learn what we can do for your restaurant."},{"type":"h2","text":"Managing Your Cash Flow"},{"type":"p","text":"As we mentioned, Point of Sale systems can by and large handle these analytics for you. By examining your cash flow from the previous year, plan a budget for the upcoming one. Look at past trends to see if there’s particular seasons or months where you tend to bring in a little extra cash or if your sales go down at any point; then you can use that information to create seasonal budgets for the coming year. Since cash flow tends to change from quarter to quarter, it’s better to plan that way rather than creating one flat budget for the entire year."},{"type":"p","text":"Streamlining your overhead costs also increases your overall income. Find out if you can lower your payments to vendors or utilities, edit the menu to remove poor-selling items from the list and make room for dishes that generate higher sales, or even edit your hours so you close on nights that are repeatedly slow or open early on days when people seem interested in coming by. One surefire way to trim overhead costs is by reducing food waste throughout your restaurant."},{"type":"p","text":"Try not to rely too much on credit for your purchases. Debts not only account for a massive part of cash outflow each period but they can potentially tack on interest, creating an even bigger expense overall. You should consider asking your vendors if they’ll sell to you at a discount provided you pay that cost upfront, rather than taking out the full price of the goods on credit. They have their own cash flow to consider and although some will say no thanks, others might take you up on the deal. Consider also diversifying your vendors; although it might be convenient to use the same vendor for one group of itemsfor example, having a reliable produce guyyour prices will skyrocket if something happens to their supplies. Working with multiple vendors will make it easier to circumvent this problem in the future, while also giving you other prices to compare and negotiate so you can guarantee that you’re getting the best deal."},{"type":"p","text":"However you don’t always have to reduce your spending in order to make more money. By increasing how much you put into advertisements, for example, you can potentially draw in more customers to serve which will offset the costs and have a positive impact on sales. It’s important to promote your business! Social media marketing is huge right now, but you can also bring in guests by offering discounts on off-peak hours, Groupons that pull in large crowds and more. Connect with your guests to strengthen your relationship with them and learn what your brand name needs to do to become a household fixture."},{"type":"p","text":"Connect with local businesses to create cross-promotional campaigns in each other’s stores. The more businesses and organizations you partner with, the more likely they are to hire you for additional services like catering at their parties and eventsif you offer catering. That’s another good way to pull in revenue. Learn how to launch catering services with your restaurant here."},{"type":"p","text":"The most important part of managing your cash flow is making sure your bookkeeping is accurate, up to date and well-managed. Invoicing and accounting are both extremely necessary aspects of understanding and thus managing your business. This is why it’s so helpful to have a Point of Sale system that can collect most of this data for you and analyze all of it quickly and cleanly. Always have a “rainy day” fund for emergencies so you’re not scrambling to find cash or take out loans in a pinchYou can be prepared instead."},{"type":"p","text":"With all the information you’ve gathered and these tips in mind, start being proactive: Save, reduce your costs and spend smarter wherever you can. Got more questions about managing your cash flow? Let us know, because we’re here to help."},{"type":"p","text":"#eatOS #Restaurants #SmallBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_ca545459eb0b479e969260eae410dcd1~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2021-03-05', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-manage-your-restaurant-s-labor-force', 'How to Manage Your Restaurant’s Labor Force', 'Are you tired of laboring over your restaurant’s labor costs? Laws surrounding your workforce are tricky; rules vary from state to state and sometimes even across city lines, theyre reliant on federal guidelines,...', '[{"type":"p","text":"Are you tired of laboring over your restaurant’s labor costs? Laws surrounding your workforce are tricky; rules vary from state to state and sometimes even across city lines, theyre reliant on federal guidelines, change depending on your tipping structure and affect every aspect of your business despite the mercurial nature of all these factors combined. Labor costs are a significant chunk of your monthly expenses, too, so learning to navigate labor laws will help you exercise control over a big portion of cash outflow."},{"type":"p","text":"Rising labor costs are inevitable. The minimum wage is constantly increasing and labor costs naturally rise with it since you have to spend more on your employees; however you can use pay as an advantage to incentivize better people to join your team in the first place. Better-trained, higher-quality candidates will apply to jobs with higher salaries. Full-time employees typically seek jobs that offer health insurance and other benefits, and restaurants’ general failure to provide that kind of stability is part of the reason that employee turnover is so high throughout the industry. Well-paid staff are happy staff, and happy staff work harder and stick around longer."},{"type":"p","text":"Pay attention to overtime, as that’s another huge chunk of labor cost right there. Know which employees are nonexempt, part-time and how many hours each person can work. Keeping track of employee hours lets you prevent people from going into overtime and unnecessarily costing you money. Overtime increases when the minimum wage does, so reducing it cuts out a big expense."},{"type":"p","text":"Scheduling also has a huge impact on your employees’ mental health. Generally, the food service industry has a bad reputation for swiftly-changing schedules, unexpected overtime and shifts cut short. Sticking to a promised schedule adds stability to employees’ lives and makes it easier for them to establish an acceptable work-life balance that fosters better mental health. If possible, make steady schedules too so the employees can plan their personal lives ahead of time."},{"type":"p","text":"You can reduce your labor costs by properly training everyone brought on board. Cross-training your staff not only gives them a chance to round out their industry skills and become better-fitted for a future career, but this investment in them also pays off because your servers can act as runners, bussers and hostsso you dont need to hire those roles. Flexibility on their end equals better preparation for their career and fewer labor costs for you."},{"type":"p","text":"Join relevant organizations to stay informed, build a network of other restaurants that inform you about ever-changing labor laws, create opportunities to share ideas and stories, and make friends in the area. Between allies and a strong team, you can create a stronger organization."},{"type":"p","text":"You can reduce turnover rates by treating your employees with respect and demonstrating your investment in them, so they in turn want to give you their full commitment. Managing your labor force isn’t always about cutting costs but is sometimes just treating employees as equals. These simple steps will go a very long way toward reducing your expensesand improving your operations and bottom line, too."},{"type":"p","text":"#eatOS #WorkforceManagement"}]', 'https://static.wixstatic.com/media/a77ed6_2439da65ffc14fff8135be5cb036e925~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-03-03', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-market-your-restaurant', 'How to Market Your Restaurant', 'New or old, all restaurants are looking for ways to get their name out there. Whether you’re launching your business from the ground-up or simply updating your strategy to excel in the digital age, any small business...', '[{"type":"p","text":"New or old, all restaurants are looking for ways to get their name out there. Whether you’re launching your business from the ground-up or simply updating your strategy to excel in the digital age, any small business can benefit from developing pointed. Thought-out marketing techniques that build brand awareness, strengthen customer relationships and highlight the successes of your restaurant."},{"type":"p","text":"Here at eatOS, we’ve developed this list of strategies for successfully marketing your restaurant onlineand keeping those new customers once you draw them in."},{"type":"h2","text":"Loyalty Programs"},{"type":"p","text":"One of the best ways to ensure customers continue giving you patronage is through reward and loyalty programs that show your appreciation for their continued support. Offering free purchases, discounts, etc. encourages customers to keep coming back to win that prize."},{"type":"p","text":"There are many online apps available to make it easy to implement loyalty programs. You can even use partnerships with third party delivery platforms to draw customers in, by offering discounts if they order directly from your website next time and then from there setting them up in the rewards program. Alternatively, you could go old-school and give out punch cards."},{"type":"h2","text":"High-Quality Photos"},{"type":"p","text":"It’s easy to draw in new customers by the look and smell of your restaurant as they pass by on the street, but harder to convey that same feeling over the internet. Including good, high-res pictures on the menu will encourage more people to try out the food. You can show off your bestselling dishes or promote items that don’t usually sell as well, drawing attention to that part of the page so customers give it a second look. Also, consider adding photos to your website immediately entice people when they navigate to your page. It doesn’t have to stop at food, either: Show off different aspects of the business to create a well-rounded idea of your establishment before setting foot in the door. Which leads us to…"},{"type":"h2","text":"Social Media"},{"type":"p","text":"Having a strong social media presence is paramount toward building a strong brand. It’s 2020, and everything is online nowif not, then that’s where most advertising takes place. People, especially younger generations, spend so much time on the internet that you’re missing out on a considerable portion of your potential customer base by neglecting that crucial sphere."},{"type":"p","text":"Don’t limit yourself to depicting food. On Instagram, for example, you can post your most delectable dishes and include photos of the storefront, customers enjoying your cuisine, and even your staff’s hard work. Its beneficial to include staff in social media posts because it strengthens your reputation as a trustworthy, worthwhile place to spend money. When people see happy employees, they trust you more."},{"type":"p","text":"You can even publish some of your recipes so that long-time customers can enjoy their favorite dishes at home. Overall, get creative with establishing pages that show off what makes your business unique. Social media is the perfect place to strengthen your brand identity and demonstrate what makes your business great."},{"type":"h2","text":"Reviews"},{"type":"p","text":"Whether you set up your page on review sites or not, people will comment on your business. Thats why its beneficial to stay ahead of the press by establishing yourself on websites like Yelp or Tripadvisor, where you can monitor the activity regularly."},{"type":"p","text":"It’s best to meet feedback head-on, since theres no way to avoid it altogether. Even bad reviews aren’t necessarily bad for business as long as they’re handled correctly, so there’s no reason to fear them. Reviews have tremendous power in the marketplace because they’re a fast and easy way for customers to determine whether a restaurant’s food and atmosphere will suit their needs, especially when they’re visiting someplace new. That’s why it’s so important to make sure that all of your information is publicly available there and up to date: Store hours, address, menu, price range and any amenities you can boast will all round out your profile and increase your chances of coaxing in a satisfied customer."},{"type":"p","text":"Don’t underestimate the power of the internet. Get on popular websites, like Google+, to increase your chances of showing up in relevant searches. For example, Google+ will put you on the map in your area to appear more prominently in searches with applicable keywords, like “NY seafood restaurants” or “Chinese food Los Angeles.” This leads us to"},{"type":"h2","text":"Geo-Targeted Ads"},{"type":"p","text":"When looking for someplace new to dine out, people tend to search within a specified location to narrow down the most suitable choices. Thus investing in geo-targeted ads will narrow down where you appear on searches, so you primarily show up near your targeted demographics within a specific city or radius. Ultimately this saves you money by limiting your clicks to people who have a higher chance of actually becoming a customer."},{"type":"p","text":"There are plenty of online ad platforms that geo-tag for free as part of their regular services like Facebook, Twitter and other ad services. Even if it costs a little money, it’s worthwhile to invest in online ad platforms that offer geo-tagging."},{"type":"h2","text":"Newsletters"},{"type":"p","text":"Direct marketing is the best way to keep up with your customers, but you need to strike a careful balance so you dont overload them. Email marketing is the most effective method for building customer relationships in this manner, but be careful: Sending letters out more than once or maybe twice a month will result in many un-subscribers. People are inundated with email marketing campaigns day in and day out, so yours has to be really impactful, informative, and infrequent enough that it’s worthwhile for them to stay."},{"type":"p","text":"If you can strike the right balance, though, email newsletters will become invaluable. Direct marketing makes it easy to reach out about new dishes, discounts and promotions that cater to their specific interests. Find free email campaign templates, or tools to create your own, online."},{"type":"p","text":"Direct marketing develops your brand identity and forms deeper bonds with your customers, so they genuinely want to interact with you more. Alternatively, or supplementary to your newsletter, you can start a company blog to talk more in-depth about your restaurant, including behind-the-scenes sneak peeks of your operations, recipes you’d like to share, or anything else that will help develop a strong brand identity. A blog will help further cultivate your community and engagement statistics."},{"type":"h2","text":"User-Generated Content"},{"type":"p","text":"User-generated content, or UGC, is a phenomenal marketing tool for any restaurant looking to grow their following and connect with their customers more intimately. Essentially, UGC encapsulates any content thats made by an unpaid third party. Any time a customer posts a picture of their dinner and tags you, that’s UGC. You can encourage this engagement by hosting contests on your social media, wherein people submit photos, tag you, and then select a winner via lottery or some other method. You can offer up a free appetizer, discount code or whatever you decide to use as an incentive."},{"type":"p","text":"Reposting or thanking those accounts who participate will show your appreciation for those customers, strengthening your bond while simultaneously garnering more customers from them. Typically people trust recommendations more when a friend or acquaintance has made them, so UGC is essentially advertising to their entire newsfeed for free. Supporting user-generated content is good for business."},{"type":"h2","text":"Advertise Good Press"},{"type":"p","text":"When someone says something good about your business, they’ve done most of the work already: All you have to do is distribute that recommendation to an even wider audience, thus doubling the initial viewership that they would get alone. This is why it’s crucial to have Google alerts for your business’s name, so you can quickly see content published in your favor. Consider setting up an “In the Press” or similar page on your website makes it easy for visitors to see that positive press easily."},{"type":"p","text":"These are just a few ways to market your restaurant, though you should use it as a jumping-off point and build on it all the time. There are more intensive, more expensive avenues you can take too: For example, third party delivery apps will take a marketing fee and automatically spread your name to their hefty, built-in customer base."},{"type":"p","text":"Using our techniques and ideas, though, you’ll have a good idea of how to begin marketing your restaurant online and building a community of dedicated customers who will value you just as much as you value them. Good marketing is the cornerstone of great success."},{"type":"p","text":"#eatOS #RestaurantMarketing"}]', 'https://static.wixstatic.com/media/a77ed6_23e6da178de649368ed8424c6d1934fc~mv2.jpeg', 'Marketing & Loyalty', 'eatOS Staff', '2021-02-26', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-minimize-restaurant-labor-costs', 'How to Minimize Restaurant Labor Costs', 'Labor costs are one of the highest expenses for restaurants, in part because it’s one of the more difficult variables to control. Labor is necessary; you can’t get through a dinner rush without good cooks and...', '[{"type":"p","text":"Labor costs are one of the highest expenses for restaurants, in part because it’s one of the more difficult variables to control. Labor is necessary; you can’t get through a dinner rush without good cooks and well-trained servers."},{"type":"p","text":"As restaurants struggle with overstaffing problems, high turnover, rising minimum wage, and labor laws in flux, they’re increasingly relying on these five ways to reduce labor costs."},{"type":"h2","text":"1\\. Streamline staff schedules"},{"type":"p","text":"Over- and understaffing are real problems for restaurant owners on a day-to-day basis. As sales fluctuate depending on the season, day of the week, mealtime, nearby events, upcoming holidays, and many other factors, management needs to assess all of these variables when making the schedule."},{"type":"p","text":"Smart technology is here to help. Advanced Point of Sale systems track data so you can see how busy you’ll be based on sales history; that informs how many employees you’ll need a different work station on any given night. Integrate scheduling software like 7Shifts, which significantly reduces how long you spend working out shifts and lets employees swap them online without managerial approval. You don’t have to worry about last-minute call-outs and no-shows giving you a headache."},{"type":"h2","text":"2\\. Improve management"},{"type":"p","text":"Optimize your managerial team to watch that good behavior trickle down to junior roles. Managers are supposed to keep the business running how you want even when you’re not around, so equip them with the skills and knowledge to do so effectively. Convey your professional goals so they know exactly how to keep the restaurant at peak efficiency; for example, track of employee hours so they don’t go into overtime."},{"type":"h2","text":"3\\. Hire smarter"},{"type":"p","text":"Invest in staff from the get-go, so they start on the right path. Employee turnover is a massive problem for restaurants, as continually recruiting and training new workers leads to high labor costs. Improve your job posts to attract better-qualified candidates by offering competitive pay and benefits so they’re motivated to work harder. Cross-train employees to improve their overall efficiency and the likelihood that they’ll stay loyal to your brand as you equip them with relevant skills and show your investment in their long-term career."},{"type":"h2","text":"4\\. Treat your workforce well"},{"type":"p","text":"Taking on a mentorship role motivates your staff to work harder, which improves your labor cost percentage. Show how much you appreciate their sacrifices by celebrating their achievements, gifting rewards for those servers who net the most profit or taking hardworking shifts out for a company dinner. Even a direct thank-you goes a long way. Use pre-shift meetings to highlight superstar workers, clarify aspects of the business the team handles well, and showcase the month’s employees to encourage the rest of the staff to follow in their footsteps."},{"type":"p","text":"Show your employees where they fit into the grand scheme of operations so they see how their everyday actions matter and how they affect the rest of the team and the workflow throughout the chain of command. Improving their productivity bolsters the rest of operations, so streamlining all your workers will reduce labor cost significantly."},{"type":"h2","text":"5\\. Cutting-edge technology"},{"type":"p","text":"Invest more now to get more later. Spending money on advanced Point of Sale systems like the one powered by eatOS ultimately gives you access to superior reporting and analytics, workforce management features, integrated scheduling software, and more so you reduce your labor cost percentage in the long run. Short-term investments save you more later."},{"type":"p","text":"Schedule a demo with eatOS to learn how we’re ushering in the future of food service, today."},{"type":"p","text":"#eatOS #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_cea3bc13b9764f80ae92d980bf371516~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-02-24', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-optimize-your-menu-for-travel', 'How to Optimize Your Menu for Travel', 'Since COVID-19 irrevocably changed the restaurant world, many businesses that never bothered with online ordering systems before suddenly found themselves scrambling to open up new channels for takeout and delivery....', '[{"type":"p","text":"Since COVID-19 irrevocably changed the restaurant world, many businesses that never bothered with online ordering systems before suddenly found themselves scrambling to open up new channels for takeout and delivery. Social distancing makes dining in dangerous, while third party delivery platforms often take high commission fees that are untenable for struggling businesses."},{"type":"p","text":"When adapting a menu for online ordering, you need to optimize the food for travel and figure out how to balance profitability with dishes that can survive the ride. It’s different than figuring out in-house menus because you need to make up the cost of delivery and still guarantee that food ends up fresh and delicious in the customer’s hands."},{"type":"p","text":"How can you get your menu fit for online ordering?"},{"type":"h2","text":"Tips to Remember"},{"type":"p","text":"Guaranteeing that your food stays fresh and just as good as what you serve in-house is tough but worthwhile, because it can vastly improve profits in the long run. Online ordering is the reason so many businesses made it these many months of COVID-19."},{"type":"p","text":"1. Curate your menu. Unfortunately, you can’t serve everything that you offer in-house. To stay on par with your brand and make your food as good as it should be, remove items that won’t hold up in transit and replace them with similar dishes that will better weather the distance."},{"type":"p","text":"2. Separate high-moisture items. Things like sauces should be packaged on the side, because when food comes pre-made with toppings it can get soggy and taste worse."},{"type":"p","text":"3. Punch a hole for steam. Hot food needs to let out steam so that what’s inside stays crispy, crunchy or whatever consistency it’s meant to be. Don’t bother doing this with items like soup or anything that spills, but for items like fries, this will help keep them the ideal texture and taste."},{"type":"p","text":"4. Separate hot and cold. Temperature-control is one of the most difficult but necessary aspects of delivery. If the drive takes an unexpectedly long time, or the courier makes multiple deliveries in one run, separately bagging items with vast temperature differences will keep the meal copacetic."},{"type":"p","text":"5. Use compartmented containers. Not only does this improve overall presentation, but it keeps foods separate so they don’t intermingle. Don’t risk bad reviews about soggy, subpar foods; though these containers are slightly more expensive, they add a little something extra to delivery and make customers more eager to entrust their online ordering with you again."},{"type":"p","text":"6. Include reheating instructions. Just like people often take home leftovers at the restaurant, people are also likely to store away some delivery after the fact.. It breeds loyalty if customers can enjoy a good meal for days on end. The average customer won’t know how to go in for seconds except hitting a few buttons on a microwave, so add instructions on the receipt, on a notecard included with the order, or as part of the packaging such as on the tape that seals the boxes shut."},{"type":"p","text":"7. Show don’t tell. Get people ready for their order by demonstrating what they can expect when they dine with you. Post pictures of your plated meals and what dishes might look like if eaten at home and post them to your social media so customers can easily visualize what it’s like to order from you. Getting them thinking about your food is the first step toward making a customer for life."},{"type":"p","text":"8. Determine a delivery radius. Figuring out what will keep food safe and high-quality without losing money on a long delivery route means determining the optimal radius to offer customers. You don’t want food sitting in the car or on the back of a bike for more than an hour because that risks the food’s temperature falling into an inedible danger zone."},{"type":"p","text":"9. Provide a good experience. With delivery, customers are paying the same price they would in-house without the ambience or good customer service they get with dine-inplus a delivery fee. Invest in small ways to maintain your brand on online orders and get creative with hospitality, so customers feel like they’re getting what they pay for."},{"type":"p","text":"Developing an online order system could be exactly what your restaurant needs to continue thriving. Optimizing your menu for travel takes time, but when its done right, you can turn the whole system into a good marketing tactic. Promote your curated menu as a special, delivery-only deal that customers will want to take advantage of, and potentially bring in altogether new audiences on top of satisfying your existing ones."},{"type":"p","text":"With these tips, you can now begin experimenting with online ordering systems at your restaurant. Knowing what foods can travel and what parts of the system need adjustment is key to creating a new, delivery-friendly menu that makes you and your customers much happier."}]', 'https://static.wixstatic.com/media/a77ed6_05396ddaf42e41eb8bb44964ed0d6e84~mv2.jpeg', 'Online Ordering', 'eatOS Staff', '2021-02-19', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-optimize-your-restaurant-s-rooftop-seating', 'How to Optimize Your Restaurant’s Rooftop Seating', 'The ongoing COVID-19 pandemic has made nontraditional seating venues the new normal for restaurants. With indoor seating regulations in constant flux and many customers uncomfortable with too much proximity, restaurants...', '[{"type":"p","text":"The ongoing COVID-19 pandemic has made nontraditional seating venues the new normal for restaurants. With indoor seating regulations in constant flux and many customers uncomfortable with too much proximity, restaurants have had to get creative to optimize outdoor seatingespecially if they didn’t have an area cordoned off for such a thing before. When sidewalks, parking lots and alleyways just don’t work, more and more restaurants are moving upwards instead."},{"type":"p","text":"Why is rooftop seating the most coveted new trend? It’s easy to market, good for private events, and seems both exclusive and tasteful to guests. All this makes it a great method for increasing your overall revenue. Seating more guests never hurts. Before you can move to the rooftop, though, you’ll need to make sure you’re prepared for this new kind of outdoor seating."},{"type":"h2","text":"Making the Change"},{"type":"h2","text":"Prepare the Area"},{"type":"p","text":"You’ll need to have a good setup, not only to draw in the crowds but also to prepare for the challenges of outdoor dining. Weather, for example, can be a huge detriment to business, especially depending on where you live. Even the sunniest place in the country won’t always stay warm and dry; stock tables with umbrellas, coverings, and consider retractable awnings or screens to keep out the cold and wet. The more durable your furniture, the better prepared you’ll be to recover swiftly from inevitable inclement weather."},{"type":"p","text":"Be prepared for wind, too. Even in nice weather, it will be dominant so far from the ground. To avoid cushions and decor blowing away, anchor down everything you can and use cloth napkins to provide the most trouble-free customer experience possible."},{"type":"h2","text":"Optimize Floor Space"},{"type":"p","text":"Map out your floor plan so you have a good idea of what your rooftop can handle. Knowing how many tables and guests fit up there will make it easy to start accepting reservations and booking those tables. You might also want to rent out your rooftop for private events; in that case, you’ll need to know what small, mid-size and large gatherings should look like, how many people you can have there before you’re at capacity, and what the physical arrangements will look like so you can begin preparing packages for guests."},{"type":"p","text":"Have backup plans, too, for when things do go sideways because of rainstorms, cold spells or other unforeseen circumstances. You shouldn’t kick out guests mid-meal or have no alternative when a rooftop event has to stop. In an emergency, managers should contact all reservations and encourage guests to move it to a different night with a discount or promotion attached to the offer, and set up an indoor event space to use as backup if necessary."},{"type":"h2","text":"Create a Welcoming Environment"},{"type":"p","text":"A scenic overview can be a major selling point for the restaurant, but if you dont have a nice view then you need to emphasize the positives. Do you have a beautiful skyline? Does the sunset look particularly nice? Optimize seating with the best views and decorate the sight lines that need some work. Don’t be afraid to show off: Take pictures and post them to your own social media to entice guests to come see for themselves. You should also post your social media handles on the wall, on the menu and in other visible locations so guests can tag you in their photos of their dinner or the view; not only is that free marketing to everyone on their feed, but it fosters better customer relationships and increases the likelihood of them becoming a loyal, repeat guest."},{"type":"p","text":"Even with a great view, decorate the bare spots of the rooftop to maximize the aesthetic appeal. Make the space welcoming with classic games, string lights, paintings or any other decoration that matches the rest of your brand."},{"type":"h2","text":"Ensure Accessibility"},{"type":"p","text":"Your rooftop might be an exclusive draw compared to other eateries in town, but it shouldn’t be hard to access. Stairways might be fine for some, but elderly and disabled patrons could have difficulty, so consider elevator access. Regardless you should make the way there clear with signage, include instructions in reservation confirmations, and detail the path in your marketing so guests are never lost wondering where to go."},{"type":"h2","text":"Stock up"},{"type":"p","text":"Unless you have a room for a second kitchen on the roof, your staff is going to have to go back and forth from downstairs to serve the guests up there. This presents a huge opportunity for spills and other accidents which cost you time, money and potentially customer satisfaction. Make sure you’re stocked up on everything you can leave up there: napkins, bar supplies, and extra silverware will help prevent wasted time going back and forth. The bartender should have all the necessary tools for mixing as well as a full supply of drinks so they never leave their station."},{"type":"h2","text":"Get Licensed"},{"type":"p","text":"You might assume that just because it’s taking place on top of your building means that all the usual rules and regulations apply, but that’s not the case at all. Moving outside means you need proper licensing; some onsite contracts and insurance policies will let you expand up there no trouble, but others require special applications, so make sure you’re squared away. Also check your city’s zoning regulations and licensing laws in case you need to get an exemption there too. Talk with your businesss lawyers to ensure you’re completely good to go before seating anybody up on the roof."},{"type":"h2","text":"Open for Business"},{"type":"p","text":"Now that you’ve got all your paperwork in place, your floor plan and decor are set, and you’re ready to market your rooftop seating area, you can begin taking reservations and allowing guests up on the roof."},{"type":"p","text":"The rest is in your hands: Do you want to hire some extra security for up there? Will you be setting up live music or other forms of entertainment? With the necessities out of the way, you can begin to make your rooftop seating unique and show off what makes your restaurant the best place around to dine out."},{"type":"p","text":"#eatOS #RestaurantBusiness #Restaurants #SmallBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_a053bb2c315c460cbcd249a4689e7f9b~mv2.jpeg', 'Restaurant Growth', 'eatOS Staff', '2021-02-17', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-reduce-employee-turnover-at-your-restaurant', 'How to Reduce Employee Turnover at Your Restaurant', 'Skip to Main Content', '[{"type":"p","text":"Skip to Main Content"},{"type":"h2","text":"What’s Going On With the Labor Shortage?"},{"type":"p","text":"Restaurants are experiencing a labor shortage right now. Employee turnover skyrocketed during the pandemic, creating difficulties in finding workers who would stick around long-term. Even as restaurants reopen this summer, they don’t have the staff for full capacity There are a few reasons for that, among them low pay and concerns about COVID-19. Whatever your workforce’s reasoning, restaurants are struggling."},{"type":"p","text":"The first step to reducing employee turnover is understanding yours. Calculate employee turnover by:"},{"type":"p","text":"1. Deciding what time period you want to focus on. For example, monthly or quarterly metrics are useful for comparing your restaurant against the national average."},{"type":"p","text":"2. Add together how many employees you have at the beginning of the time period versus the end. Then divide by two. That’s the average number of workers you had throughout the period."},{"type":"p","text":"3. How many workers left you this year? Take that number and divide it by the average you just calculated. Turn it into a percentage to see your turnover rate."},{"type":"p","text":"Once you have your turnover rate, see how it compares to other restaurants. With an advanced Point of Sale system, you can break down your numbers further and further until you pinpoint what’s driving off new hires. Smart POS makes that kind of streamlining easy."},{"type":"p","text":"Photo by Ketut Subiyanto from Pexels"},{"type":"h2","text":"Why Employee Turnover Matters"},{"type":"p","text":"In 2020, restaurant turnover reached 130%. That’s a significant hike from the previous year. Although restaurants no longer have legal barriers to opening, the cost of living and the wages earned at a restaurant job rarely align. Thus the people willing to work might find they can’t handle the stress without better payoff; or else it’s difficult to find candidates who are both qualified and willing. So the question is: How can your restaurant recruit suitable applicants, and then keep them?"},{"type":"p","text":"The issue goes deeper than just the costs of recruitment (which can add up to thousands of dollars to replace just one worker). The constant cycle of new hires severely impacts morale. When the team can’t bond, they’re weaker. Turnover hurts the overall workplace culture, engagement and performance. Restaurants work better when its staff has time to develop systems together and find their rhythm as a team."},{"type":"h2","text":"How to Reduce Employee Turnover Long-Term"},{"type":"p","text":"Focus on hiring the best candidates for your particular workplace; that won’t look the same for every business. Choose somebody with the makings of a good fit, even if you have to train them on important aspects of the position that a more qualified applicant would already know. It’s worth the time to invest in current employees and mentor them into the workforce you want to see."},{"type":"p","text":"When it comes to making your staff happy, ultimately they’re the ones who know best what would incentivize them to stick with the company. Talk to them directly and find out what will help them perform their jobs more effectively and make them want to stay at this particular restaurant. Then streamline your new, more productive team with a smart Point of Sale capable of superior workforce management."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurant #WorkforceManagement"}]', 'https://static.wixstatic.com/media/a77ed6_3cb6183b10514833908e69f6fc2151f1~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-02-12', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-reduce-labor-costs-in-your-restaurant', 'How to Reduce Labor Costs in Your Restaurant', 'Every restaurant has them, they’re some of your most significant expenses, but they’re also one of the best predictors of success. No, it’s not a riddle: We’re talking about labor costs. They’re so important albeit one...', '[{"type":"p","text":"Every restaurant has them, they’re some of your most significant expenses, but they’re also one of the best predictors of success. No, it’s not a riddle: We’re talking about labor costs. They’re so important albeit one of the most challenging factors to control, because its the most effective KPI for determining the viability and profitability of your restaurant."},{"type":"p","text":"It’s not just about salaries, either. “Labor costs” encompass everything from wages to bonuses, payroll tax, healthcare, vacation and sick days, and overtime too. Though it seems straightforward to view these factors as the sole indication of where to cut costs, it’s actually more useful to address the labor cost percentagethat is, your labor cost as it relates to revenue (determined either as a percentage of total sales or of total operational costs). By tracking these trends, you can better understand and address cost control."},{"type":"p","text":"Labor cost is exponentially increasing because the minimum wage is always going up, which raises everybody’s salary across the board. Thus it’s more beneficial to track the percentage and how costs relate to revenue. Most restaurants aim for a labor cost percentage that averages between 20-30%, although that number changes depending on the specific industry. For example:"},{"type":"p","text":"1. QSRs: 29.4%"},{"type":"p","text":"2. Fast-casual establishments: 28.9%"},{"type":"p","text":"3. Casual: 33.2%"},{"type":"p","text":"4. Upscale casual: 30.4%"},{"type":"p","text":"5. Pizza: 31.3%"},{"type":"p","text":"Depending on what type of restaurant you are, you now have a basis for whether you’re performing well relative to the rest of the industry. If not, it’s time to make some adjustments."},{"type":"h2","text":"Self-Service Technology"},{"type":"p","text":"Making an initial investment in advanced technology will reap greater rewards in the long term. Self-service technology puts control into the customers’ hands, ensuring more accurate orders, eliminating lines and ultimately selling more food, both because of embedded upselling capabilities and because customers are more likely to increase their cart size when they’re not relaying it to a third party."},{"type":"p","text":"In particular, kiosks are getting more popular because you can buy them stand-alone without having to upgrade your point of sale system entirely. Learn more in-depth about how self-service kiosks are revolutionizing the food service industry."},{"type":"p","text":"All these devices combine to increase check sizes and lower your labor cost; after the initial investment, they start paying for themselves in a matter of days."},{"type":"h2","text":"Point of Sale"},{"type":"p","text":"Self-service technology works best when paired with a good point of sale system, as that’s what enables your employees to do their best work. When a PoS system is equipped with the right software, you can rely on it to automatically handle certain aspects of the job like inventory management, CRM, staff management and communication, sales reports, basic marketing, labor reports and employee scheduling."},{"type":"p","text":"The last two are especially important. Knowing how to analyze a labor report tells you what adjustments need to be made to influence the labor cost percentage effectively. Learn to analyze certain days, times and even seasons to optimize your schedule better, and see what dishes perform best and when. Even minor adjustments based on these factors add up to save on labor costs."},{"type":"h2","text":"Employee Scheduling Tools"},{"type":"p","text":"PoS systems that integrate some type of scheduling software are proven to reduce labor costs by 4%. A good employee scheduling tool automatically works for you, taking human error and time out of the equation."},{"type":"p","text":"A good program will make schedules more quickly, lower your input when sourcing shifts, reduce over- and understaffing, and track and reduce costs by analyzing the labor reports for you in this capacity. 7shifts, for example, saves clients between 1-3% on labor costs. The right scheduling tool should quickly implement beneficial changes once they’re identified, so you can start saving right away."},{"type":"h2","text":"Adjust Hours"},{"type":"p","text":"Sometimes, the answer isn’t over- or understaffing but simply that you don’t get much business on, say, Tuesday nights after 10PM. If you can identify slow nights based on your point of sale system’s progress reports, you can close early on those days, or open later if its more applicable to focus your resources on peak times instead. Automatic analysis of sales and labor reports will prioritize what works so you can lose what doesn’t."},{"type":"h2","text":"Employee Training"},{"type":"p","text":"When staff members are set up for success, they’ll form a more cohesive and efficient team. Hands-on, practical training now means they’ll spend less time struggling to learn and work simultaneously, which ultimately takes longer and provides worse results. By training better employees from the jump, you can schedule fewer workers while maintaining the same level of excellent service."},{"type":"p","text":"Employees should be well-versed in using all of your onsite technology such as the point of sale system and tableside self-services devices. They should be able to troubleshoot devices for customers even if they dont use that technology on a day-to-day basis. It’s best to have new hires shadow your most experienced or best-performing employees to learn what makes an excellent member of the team, directly from the superstar’s mouth."},{"type":"p","text":"Communicate your restaurant’s standards so workers know what the job expects of them, and additionally provide easy access to the employee handbook as a reference; this prevents them from taking time out of managements with every little question and ultimately leads to fewer costly mistakes. You should also hold refresher training courses every now and then in addition to semi-frequent performance reviews. All of this reinforces your expectations and helps your staff work toward achievable progress goals. Read more about why investing in your staff critically prepares your business for future success."},{"type":"p","text":"The restaurant industry has notoriously high turnover rates; staff retention is a major struggle for most of them to overcome. Constantly hiring and training new employees takes a massive toll on revenue, which you’ll see reflected in your labor cost percentage. If you pay staff well, give them benefits and treat them with respect, they’re more likely to stick with you long-term. You can offer additional rewards to incentivize retention, such as small prizes for the best-seller or recognizing an employee of the month. You’d be surprised how far even a simple thank-you will go toward raising staff morale."},{"type":"p","text":"It would be best if you also promoted employees who do well, or give them a raise, to demonstrate that growth is possible within the organization. Effort improves when they have a goal to work toward. Everyone wants to advance their professional career forward. This is why it’s important to never, ever raise menu prices or reduce employees’ wages to try and save money, because although it may be effective in the short-term, the long term negative impact on morale, profits and customer relations will lead to massive, irreconcilable losses over time."},{"type":"p","text":"By identifying the areas of your business that need improvement, you can optimize staff’s time to maximize efficiency. That’s what makes technology so vital to the industry; point of sale systems that can evaluate all of this for you saves time and shows you concrete changes to make. Every little bit counts; the more parts of your business that you can optimize and automate, the more these small changes will add up to reduced labor cost percentage."},{"type":"p","text":"KPIs exist to help you succeed. Learn how to analyze your labor cost percentage and affect reasonable action to improve operations, maximize the efficiency of your team, and build a more successful restaurant overall."},{"type":"p","text":"#eatOS"}]', 'https://static.wixstatic.com/media/a77ed6_f904f821a5a9469c91cd96e226e86e3a~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2021-02-10', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-start-an-online-store', 'How to Start an Online Store', 'During the pandemic, restaurants searched high and low for new sales channels to tide them over. With dine-in services closed or restricted, customers turned en masse toward online ordering instead. Having an online...', '[{"type":"p","text":"During the pandemic, restaurants searched high and low for new sales channels to tide them over. With dine-in services closed or restricted, customers turned en masse toward online ordering instead. Having an online store is more popular with demographics who can’t easily walk to your restaurant. The delivery radius for your restaurant expands your potential audience beyond walk-ins."},{"type":"p","text":"Online stores are also more convenient for guests. They can add items to their cart day or night, and then simply press send when the restaurant opens. For the sake of you and your business, it’s time your restaurant got its own online store."},{"type":"h2","text":"What is eCommerce?"},{"type":"p","text":"eCommerce is the process of buying and selling items online. However, the initial understanding of that definition has expanded to mean online and physical interactions working together. This is in line with the changing needs of modern consumers."},{"type":"p","text":"For example, now they can pick up items in-store if it’s more convenient. Some digital alternatives have even applied to dine-in customers, so restaurants have considered going completely online. With QR codes, guests can scan and pull up a menu with their phones, right from their seats. Digital solutions like this rose because of COVID-19, especially as social distance made contact-free measures necessary. The more people grow comfortable with your online store, the less they want to give up the ease and efficiency of eCommerce."},{"type":"p","text":"Despite this, your online store isn’t competing with in-person services. They complement each other. Together, these channels provide the profit needed to get through this restaurant recovery period."},{"type":"p","text":"Photo courtesy of eatOS"},{"type":"h2","text":"Making a Successful Online Store"},{"type":"p","text":"Given its importance, why not make your online store as strong as possible? Connect it to an advanced Point of Sale system to get secure payment options, faster deposits, inventory management capabilities, and real-time syncing. This maximizes the potential of all your revenue streams."},{"type":"p","text":"Aside from a smart POS, increase the effectiveness of your online store by…"},{"type":"p","text":"1. optimizing your menu for mobile, especially given how on-the-go orders encompass so much of final sales."},{"type":"p","text":"2. paring down your target audience to those who spend the most time with you. eatOS Point of Sale comes with detailed sales reports that tell you who spends the most and when. That lets you build marketing campaigns geared toward their interests."},{"type":"p","text":"3. identifying what items, promotions and branding will make your eCommerce succeed."},{"type":"p","text":"4. building a website that aligns with your brand. Expand your brand recognition and potential audience by tightening your restaurant’s outward presentation."},{"type":"p","text":"As with all aspects of running a business, you get out what you put in. Dedicate yourself to your online store as much as you did with delivery and dine-in. That means promoting across your socials, offering discounts to draw in customers, and learning your store inside and out."},{"type":"h2","text":"The Power of Modern Tech"},{"type":"p","text":"Strong restaurants lean on state-of-the-art Point of Sale systems. Get the most out of your online store when you can see your sales data in real-time and analyze comparative reports for better business decisions. The pandemic has made people comfortable with digital platforms and contactless dining experiences. Thus your online store will remain profitable into the future, and it’s worth investing in now if you haven’t yet."},{"type":"p","text":"eatOS offers an all-in-one cloud-based eco-system exclusively for restaurants. From Point of Sale to Contactless Ordering, Pay & Order at Table, Kitchen Display System, Guest Facing Display, Online Ordering APP / Website and Workforce Management there is everything to help a restaurant succeed no matter the size. Click Here to Schedule a demo to learn more about how your restaurant can make a smooth transition into the world of restaurant technology made simple."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #OnlineOrdering #RestaurantBusiness #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_ddb8259dd0744169ba4ca2a655f001de~mv2.jpeg', 'Online Ordering', 'eatOS Staff', '2021-02-05', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-use-smells-to-improve-restaurant-sales', 'How to Use Smells to Improve Restaurant Sales', 'Have you heard that chewing gum while you study, then chewing the same gum during a test, helps you remember the material? In the same way, good smells cause people to recall a good night they had at your restaurant and...', '[{"type":"p","text":"Have you heard that chewing gum while you study, then chewing the same gum during a test, helps you remember the material? In the same way, good smells cause people to recall a good night they had at your restaurant and get them craving that same signature dish. Fragrance is proven to boost more sales in general. Hershey proved this by spritzing the scent of chocolate nearby where products were sold. Profits raised by 300%."},{"type":"p","text":"That’s why POS analytics now map out sales trends and preferences. The better you know your audience, the more effectively you’ll choose smells that speak to them. Keep in mind that different scents appeal to different consumers; for example, women prefer floral while men prefer smells like wood. However, you don’t want to alienate half the population. Instead develop a “signature scent” that reminds them of you whenever they pass it. If it’s common, like lemon for example, that’s ubiquitous enough that they’ll catch whiffs of it in random places and think about your restaurant."},{"type":"p","text":"Distinct smells equate to brand recognition. People also get hungry just coming near good food. Then the smell, sight and taste of well-made food encourages people to buy more at once."},{"type":"p","text":"Photo by Ales Krivec on Unsplash"},{"type":"h2","text":"How to Find Your ‘Signature Scent’"},{"type":"p","text":"For restaurants, that might be the whiff of a popular dish or fresh steak permeating the lobby. That’s right, good smells generate more foot traffic just by enticing curious passersby. Have you ever been out with friends and realized that it was dinnertime, but you didn’t plan to eat anywhere? As you’re looking around, you get pulled into a nearby store by the scent of freshly baked bread. Once you’ve looked over the menu, everyone agrees to stop in and eat. Even if nobody actually orders bread with dinner, the smell of it still convinced you all to come in, and from there it was easier to encourage a sit-down meal."},{"type":"p","text":"It’s not just food that impacts the senses. Post-pandemic, people are more aware of sanitation than ever. Appearing clean provides them with a sense of security, as they know you’re taking their health seriously."},{"type":"h2","text":"The Smells of a Quality Restaurant"},{"type":"p","text":"When you cook many different meals in a commercial kitchen, the smells can vie for who’s most powerful. Sometimes they don’t mix well together. This is all part of perfecting your signature scent."},{"type":"p","text":"Maybe you need to substitute ingredients for similar items that aren’t as pungent, for example. Finding a strong scent to encourage guests can also mean drowning out less-enticing smells, which then improves the customer experience because it’s more pleasant to be there. That’s probably why scent influences guests to stay 44% longer, ordering more food and drinks all the while."},{"type":"p","text":"Smells can make guests more calm or excited; they trigger good memories from when they’ve visited you before; they get guests to stay longer and spend more. Developing a unique scent is a fantastic marketing tool, and if you find the right flavor combination, you may keep new guests for life. As more regulars join the fold, many restaurants turn to smart Point of Sale systems to help organize and maintain their customer database. Nowadays POS manage customer profiles, track sales trends and handle so much more."},{"type":"p","text":"#RestaurantMarketing #eatOS #CustomerExperienceisitmatter #PointofSaleforRestaurants #isitmatter #RestaurantBusiness #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_fef0e047c9f240afa546e1f4a422403e~mv2.jpg', 'Restaurant Growth', 'eatOS Staff', '2021-02-03', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-write-menu-descriptions', 'How to Write Menu Descriptions', 'The menu is the focal point of your restaurant, the best sales tool in your arsenal. Since guests already pay attention to it, why not take the opportunity to optimize your menu descriptions and pull customers’...', '[{"type":"p","text":"The menu is the focal point of your restaurant, the best sales tool in your arsenal. Since guests already pay attention to it, why not take the opportunity to optimize your menu descriptions and pull customers’ interests one way or another?"},{"type":"p","text":"Make the menu sound enticing without getting too wordy. People don’t want to read paragraphs about a simple spaghetti in tomato sauce. Find small ways to indicate dishes’ quality in a way that customers can still quickly scan to find what they want, and profits will increase up to 15%. You just need to strike the right balance."},{"type":"h2","text":"Menu Descriptions Matter More Than You Think"},{"type":"p","text":"Considering what an important role the menu plays in guest decisions, of course it affects how people view your brand. Each menu description should emphasize what makes it unique and better than similar choices at a competitor. Give customers a satisfactory first experience; then they feel more encouraged to return again for the same great time."},{"type":"p","text":"Nevertheless, authenticity and transparency matters; don’t oversell what you can’t deliver. Incorporating photos can help. By including high-resolution pictures of certain dishes, you’ll get their mouths watering without ever taking a bite."},{"type":"p","text":"Good menu descriptions increase revenue, too. Just a few extra words can encourage customers to try sides or add drinks that they didn’t consider. It doesn’t cost too much time to update a menu once in exchange for long-term profit growth."},{"type":"h2","text":"Improving Your Menu Descriptions"},{"type":"p","text":"Considering the importance of good menu descriptions to the overall health of the business, you need to know how to accurately market your dishes to sway guests without overwhelming them. Maybe try…"},{"type":"p","text":"1. References to where you got the ingredients, particularly if you bought them locally. Seafood, for example, sounds better if it’s been imported off the coast of Maine rather than just saying, “crab legs in garlic butter.”"},{"type":"p","text":"2. Cross-promoting with your suppliers. Get their names out in exchange for them passing your restaurant along to other people they do business with."},{"type":"p","text":"3. Relying on the senses. Provoke interest by exciting customers’ taste and smell with your descriptors."},{"type":"p","text":"This is another place where pictures come in handy. High quality photos with appealing plating and a nice backdrop will set your dishes up for a nice shoot, as long as you use your actual food for accurate advertising."},{"type":"h2","text":"Smart Business Decisions"},{"type":"p","text":"Now you’re ready to reengineer your menu for optimized efficiency. Remember to use simple, straightforward language to convey what’s unique about each item."},{"type":"p","text":"For the finishing touch, make sure your menu works across all ordering channels. Pay close attention to the ones your loyal audience rely on the most: Mobile and online ordering has blown up in recent years and will continue to play a huge role in takeout and delivery moving forward. To provide the best service, you need superior restaurant technology."}]', 'https://static.wixstatic.com/media/a77ed6_e9f82408dd39424887bc9a08db643926~mv2.jpg', 'Restaurant Growth', 'eatOS Staff', '2021-01-29', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('how-to-write-quality-restaurant-copy', 'How to Write Quality Restaurant Copy', 'Quality restaurant copy encourages curious customers to dine with you for the first time, convinces regulars to try out new menu items, and overall increases profit by driving business to your door. Suppose you can’t...', '[{"type":"p","text":"Quality restaurant copy encourages curious customers to dine with you for the first time, convinces regulars to try out new menu items, and overall increases profit by driving business to your door. Suppose you can’t afford a full-time writer to handle your promotions, blog posts, and menu descriptions. In that case, the task may fall to someone less experienced with compelling, informative, and professional copy."},{"type":"p","text":"If that person is you, don’t panic. You can still create compelling menu descriptions (necessary for any successful online ordering platform) and make compelling marketing copy without hiring expensive outside parties to garner sufficient ROI. With just determination and intimate knowledge of your business, anyone can create a website that reflects your brand quality and voice, is optimized for mobile use, and has a layout and photos that supplement compelling content. Here’s everything you need to know about creating that copy."},{"type":"h2","text":"Better Copy"},{"type":"p","text":"When it comes to blog posts and website descriptions, everything you write should be with the underlying goal of introducing your brand to a broader audience. Search engine optimization (SEO) is a top priority: Use relevant keywords and phrases that push you to the top of search results, so you don’t get buried beneath your competition. Use Google My Restaurant to improve the likelihood of getting noticed online by relevant potential customers in your area."},{"type":"p","text":"It’s not all about drawing their eye: You have to stand out and hold customers’ attention once they click your page. The copy doesn’t have to be poetic to be effective. Identify your core strengths so you can continue to shine a spotlight on your brand’s aspects that make you truly unique. Why should a family choose you over the twenty other Italian restaurants just like you in the same neighborhood? Take every opportunity to:"},{"type":"p","text":"1. Inform your audience about changes to the restaurant’s hours, menus, aesthetic, and other big news. Announce across your socials when you create new specials, deals or form partnerships so guests can celebrate these milestones with you."},{"type":"p","text":"2. Speak with your loyal customers, employees, and management to identify what makes your brand special. What are unique attributes that only you bring to the table? Suppose you can create a compelling story about your restaurant. In that case, you and your marketing team can begin to brainstorm what direction and brand voice the restaurant should adopt in their advertising efforts and content creation in the future. This provides a reference point to follow in the future."},{"type":"p","text":"3. Make changes based on ideas sprung from your copy. It’s your business and your rules; you can experiment with the concept in any way you’d like."},{"type":"p","text":"Amidst all this, don’t forget to focus on your story."},{"type":"p","text":"How to Write Quality Restaurant Copy"},{"type":"h2","text":"Effective Storytelling"},{"type":"p","text":"People are most loyal to brands that they can relate to, connecting with them on an individual level. Designate a landing page to tell the story of how your dream came to be. You don’t need to be a prize-winning writer for this. Just be honest and explain why guests should come to support your brand. Identify what you’re known for and work it organically into the copy: Do customers love your farm-fresh ingredients? Mention how you partner with local farmers to support the economy and demonstrate how you’re part of the larger community fabric."},{"type":"p","text":"Social media is a great place to connect directly with your best customers and learn what trends they favor, from passing food fads that will fade by the end of the month to green, economic business expectations that have been sweeping the country over the past several years. When you stay informed about your customers’ value, you can focus on writing about topics that will genuinely catch their interest. Connect blog posts to your social media and your social media to your menu, so all of it links back to turning readership into sales, which is one of the ultimate goals of restaurant copy."},{"type":"p","text":"Fancy wording isn’t everything. Where copy fails, your delicious food, tempting prices, events, and partnerships are all still a draw for curious consumers. Copy and blog articles are meant to work together with the outstanding services that you already offer. Everyone has different strengths; what’s important is to identify yours and leverage these skills to your advantage. Experiment to find the style, format, audience, and content that works for your brand. When it clicks, the resulting flood of traffic and increased sales will make all that time and effort worth the ROI."},{"type":"p","text":"As you’re optimizing your website, online ordering platforms, and restaurant brand, consider making your operations more efficient with the eatOS Point of Sale system. Taking on the extra workload, you’ll quickly realize the upsides of equipping your business with automated sales reports and analytics, workforce management features, customer relationship management capabilities, and more. We help grow your profits and increase your core audience’s loyalty by streamlining operations for a better guest experience every day. Book a demo with eatOS to learn more and together, we’ll enter the future of restaurant management."},{"type":"p","text":"#eatOS #RestaurantBusiness #RestaurantMarketing"}]', 'https://static.wixstatic.com/media/a77ed6_1b7e73ae2fd24db78f9b9e5be5a12140~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2021-01-27', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('curfews-leave-restaurants-without-a-plan', 'Curfews Leave Restaurants Without a Plan', 'Since George Floyd died in police custody on March 25th, peaceful protests have broken out in every state across the country. As a result, at least forty cities including Washington D.C., Los Angeles and New York...', '[{"type":"p","text":"Since George Floyd died in police custody on March 25th, peaceful protests have broken out in every state across the country. As a result, at least forty cities including Washington D.C., Los Angeles and New York imposed daily curfews in an attempt to curb multiple protests in those areas. The unintended consequence is that restaurants and other businesses in those cities no longer know how and when they can operate under these new mandates."},{"type":"p","text":"In many states, restaurants only recently opened for full service anyway. The ongoing COVID-19 pandemic threatened companies all over and forced restaurants, like every nonessential business, to close all operations except for those that they could carry out safely, for example takeout and delivery services. Atlanta, GA was one of the few states to take advantage of stay-at-home orders expiring in May, and they’ve had a month to adjust to reopening procedures but nevertheless those services are still recent and the city as a whole is still getting used to dining out again. Many residents are still uncomfortable in public spaces and restaurants have still not gone back to normal, even a month later. L.A. County only gave the go-ahead to reopen full service restaurants on Friday, May 29th, right as the protests gained traction in L.A. The new curfews put undue strain on restaurants that are unaccustomed to reopening during the continued pandemic in the first place."},{"type":"p","text":"These issues are further exacerbated by unclear stipulations from local governments which in turn makes it difficult for managers to create rules for their workers in accordance with the new directives. Furthermore these curfews also change rapidly, often and with no warning in a further attempt to make protests difficult to organize and attend. The arbitrary impositions give businesses very little notice or guidelines on how to operate under these conditions, particularly with regard to closing. Although restaurants are deemed essential workplaces and they, along with street vendors and similar businesses, have special permissions to operate after hours in certain circumstances, there’s little direction about differentiating food service workers from others on the street at night."},{"type":"p","text":"This all leads to confusing work shifts that often change suddenly. Each individual manager decides whether to close early and send employees home in time to beat curfew, and if they choose not to, they also determine how to keep their staff safe by properly differentiating them during their commute."},{"type":"p","text":"The lack of information is further exacerbated by workers not having access to outside sources during their shifts. Many in the hospitality industry have strict guidelines not to check or even carry their phones on them while on the clock, so they can’t see when emergency alerts come in and don’t know about the restrictions until they’re already off shift and breaking curfew. Their only source of information is their employers who aren’t always transparent about the emergency alerts and city regulations, and who don’t always choose to close early enough to get their staff home in time. Workers need to be informed so that they can make decisions about their personal health and safety."},{"type":"p","text":"Some employers feel like they have no other option except to close early or in some cases close entirely. This is the best way for some to handle the confusion and simultaneously protect their staff from any risks. For some, it’s not fiscally responsible to open if they can’t operate for a full workday, especially considering the continued threat of COVID-19 shrinking their customer base."},{"type":"p","text":"On top of that, restaurant workers aren’t receiving hazard payan issue that’s plagued essential businesses for months. Restaurant employees have campaigned for higher wages for since the COVID-19 pandemic began and threatened their health and safety every day they were at work. Now, they’re still risking their wellbeing; the risks associated with coronavirus haven’t abated despite restaurants opening to dine-in services and therefore increasing workers’ face-to-face contact with customers. Many workers are also staying past curfew but don’t get sufficient guarantee that they’ll be safe from arrest on their way home. Some even lose additional money if they rely on tips: One Pizza Hut employee in Huntington Park makes most of his money from tips, but an overload of delivery orders that came in right before curfew forced him to stay late helping box pizzas, thus sacrificing all of his tips and working for suboptimal wages."},{"type":"p","text":"Employees face further obstacles because cities close a lot of public transit at night to further stymie protests and make it difficult for citizens to attend or get home. This similarly affects essential employees in cities where a lot of the workforce relies on public transportation, since low-income people make up a large portion of the service industry. Even those with their own cars worry about road closures blocking the way to and from work, as well as about getting pulled over on their commutes. This is also a concern amongst delivery workers who fear profiling and arrest while on duty. Immigrants and people of color make up a significant fraction of the service industry and they are also the ones most at risk of being stopped by police; if workers need government ID and to prove they’re an essential worker with license to stay out past curfew, they naturally fear being questioned on their way home. This concern is especially prevalent amongst undocumented immigrants who tend to work in the hospitality industry. Furthermore these employees are part of the communities most heavily affected by police brutality and they don’t want to risk any additional interaction that could get them hurt or even killed."},{"type":"p","text":"While restaurants and government officials alike continually tell the community to consider “safety first,” personal safety is impossible while essential questions remain unanswered. For example:"},{"type":"p","text":"1. How can you determine if an employee is on their way to or from work?"},{"type":"p","text":"2. Should restaurants close early to give their staff time to get home before curfew?"},{"type":"p","text":"3. How many are inundated with delivery orders immediately after curfew is announced or right before they close? How should they handle these orders: Cancel on customers or find a way to ensure the safety of the employees who stay late?"},{"type":"p","text":"4. Should workers, especially tipped workers who stay past curfew helping with other business operations, get hazard pay?"},{"type":"p","text":"5. How can we safely handle and protect employees who need to come in during curfew to keep the store running during the day? For example stockers, inventory delivery workers and drivers that need to get home?"},{"type":"p","text":"Until we answer these questions, curfews can’t safely continue. They’re meant to protect these cities but can’t do so effectively if they’re targeting citizens indiscriminately. We need clear and concise avenues to determine who is legally allowed on the streets after dark so as to ensure the continued protection of all citizens while simultaneously decreasing unethical profiling and harassment of lawful employees. Until we have such measures in place, we cannot effectively protect our local communities from police who will often open fire indiscriminately at anyone they see out on the streets after curfew, without asking questions first. Curfews cannot be lawfully and fairly enforced if restaurants demand workers stay late and the state doesn’t protect them on their way home. Local governments need to listen to the needs of business owners and formulate with a plan that will effectively protect the workers who continue to serve vulnerable communities in this time. Cities around the U.S. are now doubly fraught with clashes between protestors and police as well as the continued threat of COVID-19. We need clear procedures in place to ensure restaurant workers are equally protected as they carry out their essential business or else we risk harming the very people who serve our local communities."},{"type":"p","text":"#CoronavirusPandemic #Community #Covid19Pandemic #FoodService #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_17041ca1df0c4f4ab75b0d2528bdfd47~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2021-01-22', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('dealing-with-the-covid-19-pandemic', 'Dealing With the COVID-19 Pandemic', 'As the virus and panic spread, people, industries and even governments are taking bigger and bigger safety measures in an attempt to stop the spread and contain the damage.', '[{"type":"p","text":"As the virus and panic spread, people, industries and even governments are taking bigger and bigger safety measures in an attempt to stop the spread and contain the damage."},{"type":"p","text":"With many places banning dine-in service, others reducing their hours or staff, and many closing altogether, restaurants around the world are wondering how to handle their staff and business. Many don’t know if they’ll open again after the pandemic is over. This is uncharted territory for customers and businesses alike."},{"type":"h2","text":"What can you do?"},{"type":"p","text":"Workers are calling off sick or  worse  not calling off at all"},{"type":"p","text":"and coming in, potentially spreading the virus to others. Dine-in customers have all but dried up, though online ordering might have seen a steep uptick in popularity over the past few weeks. It’s definitely not business as usual."},{"type":"p","text":"That’s why we’re organizing this booklet to help you figure out how to manage your restaurant during this difficult and confusing time. With so many questions and so few answers, we want to help you understand how to handle sick workers, deal with the panic and manage a declining customer base as more and more people practice social isolation."},{"type":"h2","text":"Subscribe to our page to get all the latest information on managing your restaurant during the COVID-19 pandemic."}]', 'https://static.wixstatic.com/media/a77ed6_11910196c21c4b15843ec23fe07b9b96~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2021-01-20', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('do-kitchen-display-systems-really-improve-efficiency', 'Do Kitchen Display Systems Really Improve Efficiency?', 'With everyone feeling the financial burden of the COVID-19 pandemic, Kitchen Display Systems, or KDS, might seem like an unnecessary additional expense. However, KDS actually improve kitchen efficiency so you can handle...', '[{"type":"p","text":"With everyone feeling the financial burden of the COVID-19 pandemic, Kitchen Display Systems, or KDS, might seem like an unnecessary additional expense. However, KDS actually improve kitchen efficiency so you can handle more orders and improve accuracy and satisfaction. In times like these, we could all use an easy solution for bolstering the bottom line."},{"type":"h2","text":"How do KDS work?"},{"type":"p","text":"These display screens eliminate the need for tickets. They reduce reduce paper waste and have the additional benefit of allowing kitchen staff to see the whole queue, including how long each item has been on there. This ensures customers get their dishes in a timely manner and also reduces human error, greatly improving overall order accuracy. Considering how much of poor customer satisfaction stems from incorrect orders, and how much customer satisfaction affects future sales, this is a major perk of using KDS."},{"type":"p","text":"They update in real-time when someone correct or adds to an order so customers can get any alterations fixed quickly and easily. They also work together with front and back of house printers to send receipts to the correct station."},{"type":"h2","text":"Do orders really come out faster?"},{"type":"p","text":"Yes, for two reasons: Firstly, KDS helps ensure that the entire meal goes out together, so servers don’t spend time going back and forth to the kitchen to ask for that forgotten side salad. Timestamps and digitization also make sure that orders get filled in the sequence they come in, reducing customer wait time across the board. This also helps managers determine how long customers will wait on any given day or at any given time, which allows them to make decisions about staff and optimization. It also lets staff give realistic expectations to customers."},{"type":"p","text":"These KDS also allow cooks to group orders together. Let’s use a side order of fries to conceptualize this better:"},{"type":"p","text":"Say that six people in queue all want this same side. With paper tickets, cooks would have to make six individual orders of fries, wait for them to finish cooking and start all over again. This wastes a lot of time that they could better spend handling other orders. Meanwhile with a KDS, chefs would see that six people wanted the same side and they could make one huge order of fries to dole out into six containers. This significantly reduces the total time spent on making fries and helps all six customers get their side orders sooner."},{"type":"h2","text":"Improve pick-up and delivery"},{"type":"p","text":"With everyone self-isolating to flatten the curve on COVID-19, pick-up and delivery services are experiencing a boon. By integrating KDS into your POS system, you have the ability to connect the kitchen with the rest of the restaurant from any device: handheld, self-service kiosks and the POS terminal. You can also take that a step further and connect the kitchen with your online ordering system."},{"type":"p","text":"With so many restaurants forced to shut down dine-in services and little to no front of house staff on duty, giving an immediate and organized channel for customers to send their orders directly to cooks eliminates a lot of time and confusion. With so few employees available and delivery already precariously reliant on a dish’s ability to travel well, mistakes could take a lot of time to correct, if you can correct them at all. By sending orders directly to KDS, you’ll improve customer satisfaction and in times like these, every delivery counts. Building a loyal customer base that repeatedly orders from your restaurant is more crucial than ever and can stay with you long after this pandemic is over."},{"type":"p","text":"Ultimately, KDS streamlines kitchen efficiency and hastens table turn time so you can serve more customers faster, as well as significantly improving delivery speed and accuracy. Although times are tough right now for restaurants, a little investment can go a long way if you let it and will continue to benefit you long after this is all over."},{"type":"p","text":"To find out more about how KDS can help your business, schedule a demo with eatOS today."},{"type":"p","text":"#Kitchen #CloudBasedTechnologybyeatOS #kds #KitchenDisplay #CloudBased"}]', 'https://static.wixstatic.com/media/a77ed6_10fd109b3a2a41ef90f947023e67416c~mv2.jpg', 'Kitchen Operations', 'eatOS Staff', '2021-01-15', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('does-your-food-delivery-meet-covid-19-safety-standards', 'Does Your Food Delivery Meet COVID-19 Safety Standards?', 'Food delivery: Since the pandemic began, it’s been the saving grace of the restaurant community and become such a strong customer favorite that it’s set to remain a hot trend long after we’re all vaccinated. Contactless...', '[{"type":"p","text":"Food delivery: Since the pandemic began, it’s been the saving grace of the restaurant community and become such a strong customer favorite that it’s set to remain a hot trend long after we’re all vaccinated. Contactless service options have become prolific enough that customers expect online ordering solutions that safeguard them against COVID-19. Why not be part of the answer?"},{"type":"p","text":"Streamlining the delivery system at your restaurant means making safer business decisions for everybody. FDA regulations taken into account already, you should check the rules in your specific state to guarantee complete compliance."},{"type":"p","text":"How can you make safer food deliveries overall?"},{"type":"p","text":"Does Your Food Delivery Meet COVID-19 Safety Standards?"},{"type":"h2","text":"Guarantee Food Safety"},{"type":"h2","text":"Labels"},{"type":"p","text":"Delivery drivers and in-house workers need to know when food was made and what’s in each package so they can be sure they’re bringing the right order to each door. Reduce human error by labeling each package so you get fewer calls about wrong orders, which can really add up over time. Whether you use your own couriers or a third party service, delivery runs smoother with labels."},{"type":"h2","text":"Package and Protect"},{"type":"p","text":"Your packaging matters. For example, choosing paper over styrofoam will resonate with eco-conscious customers who appreciate feeling like you share their morals and values; that little choice could win you at least one loyal visitor for life. Consider the type of packaging as well as whether it has compartments so food doesn’t slide around, if it’s tight enough to prevent spills and leaks, and if you should ventilate to prevent soggy food on arrival."},{"type":"h2","text":"Food Temperature"},{"type":"p","text":"It’s not enough for cooks to make each dish hot or cold as it needs to be on arrival; you have to take travel time into account. Coordinate your system so either everything gets cooked a little hotter than it needs to be, guaranteeing that it arrives at an appropriate temperature, or invest in well-sealed packaging so food gets to the door similar to how it comes out of the kitchen."},{"type":"h2","text":"Transportation"},{"type":"p","text":"First you need to decide whether you want to use your own or a third party service; with eatOS we’ll give you a personalized, branded merchant app to get your online ordering system up and running quickly. Unlike with third party apps, you get to keep all the profit."},{"type":"p","text":"With that decision made, you should consider the mode of transportation as well. A bike versus a car might change your delivery radius because it will affect meals’ qualities on arrival."},{"type":"p","text":"Does Your Food Delivery Meet COVID-19 Safety Standards?"},{"type":"h2","text":"The Future of Food Service"},{"type":"p","text":"Make a commitment to health and safety this New Year. As the COVID-19 pandemic hopefully winds down, let’s help end it by pledging to make smarter, safer delivery decisions. From FDA safety standards to contactless options and mobile ordering that let people social distance to their comfort, the future of food delivery can be safer, streamlined and profitable. How?"},{"type":"p","text":"Make eatOS technology solutions your own. We’ll set you up with orderOS, your personalized merchant app, and an online ordering platform where you reap all the profits. We streamline communication between your front and back of house, make payroll easier and automate relevant reports for better budgeting decisions. Enjoy these benefits, better delivery and more: It all starts with booking a demo. Let’s enter the future of food delivery stronger, smarter and safer in 2021."},{"type":"p","text":"#eatOS #CoronavirusPandemic #Covid19Pandemic #RestaurantBusiness #FoodDelivery #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_6ca8ea43fdd74e2b9feae3e0b00176ac~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2021-01-13', 'published');
INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES ('does-your-restaurant-need-more-workers-or-just-self-service', 'Does Your Restaurant Need More Workers, or Just Self-Service?', 'Restaurants have spent 2020 adjusting to new systems and revenue sources, but as the world eventually moves beyond COVID-19, dine-in services are going to need to be as streamlined as your delivery operations certainly...', '[{"type":"p","text":"Restaurants have spent 2020 adjusting to new systems and revenue sources, but as the world eventually moves beyond COVID-19, dine-in services are going to need to be as streamlined as your delivery operations certainly are by now."},{"type":"p","text":"When the business finally picks up, you’ll find yourself trying to navigate the old industry landscape, complete with ever-changing consumer trends and Point of Sale tech breakthroughs. Restaurant technology always advances alongside consumer preferences and restaurateurs’ needs. You can hire more employees to meet the surge in demand or invest in self-service devices like the Kiosk by eatOS. Is the night shift too busy to clean up, habitually leaving messes for the opening shift? Our Kiosk helps handle the rush, so you can dispatch a few workers to get started on closing tasks in time."},{"type":"p","text":"Kiosks used to be an exclusive perk of chain restaurants, but not anymore. With labor costs, a burdensome expense to wrangle, and profit margins habitually thin, investing in self-service technology might be precisely the revitalization your restaurant needs."},{"type":"h2","text":"Why not hire more workers?"},{"type":"p","text":"When you’re flooded with new business, your instinct may be to meet the influx of more workers. It makes sense, primarily because they would slot into current operations with minimal shock to things’ overall flow. Unfortunately, this isn’t the simple solution it seems: Minimum wage has been rising steadily for years and continues to be one of the reasons that industry labor costs are so high. Instead of shelling out even more on your employees, meaning you’ll have to make even more profit on average to make up for the expense, or you can find a smarter alternative."},{"type":"p","text":"All around the country, no matter what style of restaurant they prefer, customers are interested in technology solutions like our Kiosk. It’s not just a preference: More and more often, guests _expect_ self-service. They want the option to handle the transaction themselves to create a ticket with their exact specifications. Self-service provides less chance for human error, shortens lines, and hastens turn times, so all your customers get better service faster."},{"type":"h2","text":"What makes Kiosks superior?"},{"type":"p","text":"When customers can choose their entire order without communicating through a mediator, they checkout faster, which shortens the cashier’s line and everybody else’s wait times as a result. Give every customer frictionless service with a PoS system that sends orders straight to the kitchen so cooks can get started on their meals right away. Kitchen Display Screens by eatOS automatically input orders to the kitchen’s screen, so guests don’t have to wait for servers to walk to the back of the house. You serve more guests in a day, every day, thus improving your overall profits and potentially garnering more loyal customers too."},{"type":"p","text":"Add just one Kiosk to your existing lineup of servers; despite the initial investment, you’ll make your money back in just one shift if you employ our technological solutions rather than hiring an extra worker and spending time and money to train them on the job."},{"type":"p","text":"Does Your Restaurant Need More Workers, or Just Self-Service?"},{"type":"p","text":"When bosses introduce technology solutions, their employees fear it’s going to replace their job. This isn’t the case at all: eatOS Self-Service Kiosk adds revenue opportunities and works alongside your existing staff to boost turn times. They allow your workers to spend time in areas of the business that need more attention. For example, servers can get to know each table better, which lets you perfect your targeted marketing campaigns and know which deals and specials to offer that intrigue your core audience’s palate."},{"type":"p","text":"eatOS Point of Sale works _with_ your existing staff members to bolster your operations’ overall efficiency so your workers can focus on the human aspects of the job that technology doesn’t cover. We process transactions faster, make it easier to calculate tips, speed up turn times, and more, all with our state-of-the-art Point of Sale and associated devices that make restaurant management simple. Meanwhile, your staff can get to talking with loyal customers to help you make more informed business decisions."},{"type":"p","text":"Book a demo with eatOS, and we’ll introduce you to just how effective technology combined with your exceptional staff can be. The future of foodservice is nowhere."},{"type":"p","text":"#SelfServiceKiosks #eatOS #PointofSaleforRestaurants #RestaurantBusiness #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_bda3f5ce01d74d6382fe19f3170b1ac6~mv2.jpg', 'Self-Service Kiosk', 'eatOS Staff', '2021-01-08', 'published');
